-- ECO Healthy Enterprise ERP v5.0
-- Fresh install + versioned, re-runnable migrations for Supabase/PostgreSQL 15+
-- Production data is never seeded automatically. Demo data is installed only through eco_install_demo_data().

begin;

create extension if not exists pgcrypto;
create extension if not exists btree_gist;

create table if not exists public.eco_schema_migrations (
  version text primary key,
  description text not null,
  checksum text not null,
  applied_at timestamptz not null default now()
);

do $migration$
begin
if not exists (select 1 from public.eco_schema_migrations where version='001_core') then

create table public.eco_organizations (
  id uuid primary key default gen_random_uuid(), legal_name text not null, trade_name text not null,
  country_code char(2) not null default 'EG', base_currency char(3) not null default 'EGP', timezone text not null default 'Africa/Cairo',
  created_at timestamptz not null default now(), is_demo boolean not null default false
);
create table public.eco_branches (
  id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.eco_organizations(id), code text not null, name text not null,
  country_code char(2) not null default 'EG', currency char(3) not null default 'EGP', timezone text not null default 'Africa/Cairo', active boolean not null default true,
  created_at timestamptz not null default now(), unique(organization_id,code)
);

create table public.eco_roles (code text primary key, name_ar text not null, requires_mfa boolean not null default false, pii_scope text not null default 'NONE' check(pii_scope in('NONE','MASKED','ASSIGNED','TEAM','ALL')));
insert into public.eco_roles(code,name_ar,requires_mfa,pii_scope) values
('ceo','الرئيس التنفيذي',true,'ALL'),('investor_readonly','مستثمر - قراءة فقط',false,'NONE'),('system_admin','مسؤول النظام',true,'ALL'),
('finance_controller','المراقب المالي',true,'ALL'),('accountant','محاسب',true,'ALL'),('sales_manager','مدير المبيعات',false,'TEAM'),('sales_agent','موظف مبيعات',false,'ASSIGNED'),
('retention_lead','مسؤول التجديد والاحتفاظ',false,'TEAM'),('cs_agent','خدمة العملاء',false,'ASSIGNED'),('operations_manager','مدير العمليات',false,'MASKED'),
('kitchen_planner','مخطط المطبخ',false,'NONE'),('kitchen_operator','مشغل المطبخ',false,'NONE'),('qa_officer','مسؤول الجودة',false,'NONE'),
('logistics_manager','مدير اللوجستيات',false,'MASKED'),('dispatcher','مسؤول التوزيع',false,'MASKED'),('rider','مندوب التوصيل',false,'ASSIGNED'),
('growth_analyst','محلل النمو',false,'NONE'),('auditor_readonly','مدقق - قراءة فقط',true,'MASKED')
on conflict(code) do update set name_ar=excluded.name_ar,requires_mfa=excluded.requires_mfa,pii_scope=excluded.pii_scope;

create table public.eco_permissions (code text primary key, description text not null, sensitive boolean not null default false);
create table public.eco_role_permissions (role_code text not null references public.eco_roles(code) on delete cascade, permission_code text not null references public.eco_permissions(code) on delete cascade, primary key(role_code,permission_code));

create table public.eco_employees (
  id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.eco_organizations(id), auth_user_id uuid unique references auth.users(id) on delete set null,
  employee_number text not null unique, full_name text not null, email text not null unique, phone text, status text not null default 'INVITED' check(status in('INVITED','ACTIVE','SUSPENDED','DEACTIVATED')),
  hired_at date, deactivated_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), is_demo boolean not null default false
);
create table public.eco_employee_invitations (
  id uuid primary key default gen_random_uuid(), employee_id uuid not null references public.eco_employees(id) on delete cascade, invited_email text not null, auth_user_id uuid references auth.users(id) on delete set null,
  token_hash text unique, expires_at timestamptz not null default(now()+interval '72 hours'), accepted_at timestamptz, revoked_at timestamptz, invited_by uuid references public.eco_employees(id), created_at timestamptz not null default now()
);
create table public.eco_employee_role_assignments (
  id uuid primary key default gen_random_uuid(), employee_id uuid not null references public.eco_employees(id) on delete cascade, role_code text not null references public.eco_roles(code),
  effective_from date not null, effective_to date, approved boolean not null default false, approved_by uuid references public.eco_employees(id), approved_at timestamptz,
  created_by uuid references public.eco_employees(id), created_at timestamptz not null default now(), check(effective_to is null or effective_to>=effective_from),
  exclude using gist(employee_id with =,role_code with =,daterange(effective_from,coalesce(effective_to,'infinity'::date),'[]') with &&) where(approved)
);
create table public.eco_teams (id uuid primary key default gen_random_uuid(), branch_id uuid not null references public.eco_branches(id), code text not null, name text not null, manager_employee_id uuid references public.eco_employees(id), active boolean not null default true, unique(branch_id,code));
create table public.eco_team_members (id uuid primary key default gen_random_uuid(), team_id uuid not null references public.eco_teams(id) on delete cascade, employee_id uuid not null references public.eco_employees(id) on delete cascade, effective_from date not null, effective_to date, unique(team_id,employee_id,effective_from));
create table public.eco_session_revocations (id uuid primary key default gen_random_uuid(), employee_id uuid not null references public.eco_employees(id), revoked_before timestamptz not null default now(), reason text not null, actor_id uuid references public.eco_employees(id), created_at timestamptz not null default now());
create table public.eco_employee_devices (id uuid primary key default gen_random_uuid(), employee_id uuid not null references public.eco_employees(id), device_fingerprint_hash text not null, last_seen_at timestamptz not null default now(), revoked_at timestamptz, unique(employee_id,device_fingerprint_hash));

create table public.eco_zones (id uuid primary key default gen_random_uuid(), branch_id uuid not null references public.eco_branches(id), code text not null, name_ar text not null, far_zone boolean not null default false, weekly_delivery_only boolean not null default false, default_delivery_fee numeric(14,2) not null default 0 check(default_delivery_fee>=0), active boolean not null default true, unique(branch_id,code));
create table public.eco_delivery_windows (id uuid primary key default gen_random_uuid(), branch_id uuid not null references public.eco_branches(id), code text not null, name_ar text not null, start_time time not null, end_time time not null, capacity_stops integer, active boolean not null default true, unique(branch_id,code));

create table public.eco_customers (
  id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.eco_organizations(id), customer_number text not null unique,
  full_name text not null, normalized_phone text not null, phone_display text not null, email text, status text not null default 'ACTIVE' check(status in('ACTIVE','INACTIVE','BLOCKED','ARCHIVED')),
  marketing_consent boolean not null default false, consent_purposes text[] not null default '{}', consent_updated_at timestamptz,
  first_paid_at timestamptz, created_by uuid references public.eco_employees(id), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), is_demo boolean not null default false,
  unique(organization_id,normalized_phone)
);
create table public.eco_customer_addresses (
  id uuid primary key default gen_random_uuid(), customer_id uuid not null references public.eco_customers(id) on delete cascade, label text not null default 'الرئيسي', address_line text not null,
  zone_id uuid not null references public.eco_zones(id), latitude numeric(9,6), longitude numeric(9,6), map_url text, delivery_window_id uuid references public.eco_delivery_windows(id), active boolean not null default true,
  created_at timestamptz not null default now(), is_demo boolean not null default false
);
create table public.eco_customer_assignments (
  id uuid primary key default gen_random_uuid(), customer_id uuid not null references public.eco_customers(id) on delete cascade, employee_id uuid not null references public.eco_employees(id), assignment_type text not null check(assignment_type in('SALES_OWNER','RETENTION_OWNER','CS_OWNER')),
  effective_from date not null, effective_to date, assigned_by uuid references public.eco_employees(id), created_at timestamptz not null default now(), check(effective_to is null or effective_to>=effective_from),
  exclude using gist(customer_id with =,assignment_type with =,daterange(effective_from,coalesce(effective_to,'infinity'::date),'[]') with &&)
);
create table public.eco_customer_dietary_rules (id uuid primary key default gen_random_uuid(), customer_id uuid not null references public.eco_customers(id) on delete cascade, rule_type text not null check(rule_type in('ALLERGY','STRICT_EXCLUSION','PREFERENCE','NOTE')), description text not null, severity text not null default 'MEDIUM', active boolean not null default true, purpose_consent boolean not null default true, created_by uuid references public.eco_employees(id), created_at timestamptz not null default now());
create table public.eco_customer_timeline (id uuid primary key default gen_random_uuid(), customer_id uuid not null references public.eco_customers(id) on delete cascade, event_type text not null, entity_type text, entity_id uuid, summary text not null, occurred_at timestamptz not null default now(), actor_id uuid references public.eco_employees(id), metadata jsonb not null default '{}');
create table public.eco_tickets (id uuid primary key default gen_random_uuid(), customer_id uuid not null references public.eco_customers(id), ticket_number text not null unique, category text not null, severity text not null default 'NORMAL', status text not null default 'OPEN', assigned_employee_id uuid references public.eco_employees(id), description text not null, resolution text, opened_at timestamptz not null default now(), closed_at timestamptz, is_demo boolean not null default false);

create table public.eco_lead_sources (code text primary key, name_ar text not null, active boolean not null default true);
insert into public.eco_lead_sources(code,name_ar) values ('WHATSAPP','واتساب'),('WEBSITE','الموقع'),('META','Meta Ads'),('PHONE','مكالمة'),('REFERRAL','ترشيح'),('ORGANIC','Organic'),('PROMO','Promo Code'),('MANUAL','إدخال يدوي'),('CORPORATE','شراكة شركات') on conflict(code) do update set name_ar=excluded.name_ar;
create table public.eco_campaigns (id uuid primary key default gen_random_uuid(), branch_id uuid not null references public.eco_branches(id), code text not null unique, name text not null, channel text not null, start_date date not null, end_date date, status text not null default 'DRAFT', created_at timestamptz not null default now());
create table public.eco_marketing_spend_daily (id uuid primary key default gen_random_uuid(), campaign_id uuid not null references public.eco_campaigns(id), spend_date date not null, media_spend numeric(14,2) not null default 0, agency_allocation numeric(14,2) not null default 0, creative_spend numeric(14,2) not null default 0, influencer_spend numeric(14,2) not null default 0, promo_subsidy numeric(14,2) not null default 0, acquisition_commission numeric(14,2) not null default 0, currency char(3) not null default 'EGP', unique(campaign_id,spend_date));
create sequence public.eco_lead_number_seq start 1000;
create table public.eco_leads (
  id uuid primary key default gen_random_uuid(), branch_id uuid references public.eco_branches(id), lead_number text not null unique default('LEAD-'||to_char(current_date,'YYMM')||'-'||lpad(nextval('public.eco_lead_number_seq')::text,6,'0')),
  full_name text not null, normalized_phone text generated always as(regexp_replace(phone,'[^0-9+]','','g')) stored, phone text not null, email text, source_code text not null references public.eco_lead_sources(code), campaign_id uuid references public.eco_campaigns(id),
  stage text not null default 'NEW' check(stage in('NEW','CONTACTED','QUALIFIED','PROPOSAL_SENT','AWAITING_PAYMENT','WON','LOST','REACTIVATION')),
  assigned_employee_id uuid not null references public.eco_employees(id), created_by uuid references public.eco_employees(id), first_contact_at timestamptz, first_response_at timestamptz, last_contact_at timestamptz, next_action_at timestamptz,
  lost_reason_id uuid, notes text, customer_id uuid references public.eco_customers(id), first_paid_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), is_demo boolean not null default false
);
create table public.eco_lost_reasons (id uuid primary key default gen_random_uuid(), code text not null unique, name_ar text not null, active boolean not null default true);
alter table public.eco_leads add constraint eco_leads_lost_reason_fk foreign key(lost_reason_id) references public.eco_lost_reasons(id);
create table public.eco_lead_activities (id uuid primary key default gen_random_uuid(), lead_id uuid not null references public.eco_leads(id) on delete cascade, activity_type text not null, summary text not null, occurred_at timestamptz not null default now(), actor_id uuid references public.eco_employees(id), next_action_at timestamptz, metadata jsonb not null default '{}');
create table public.eco_conversations (id uuid primary key default gen_random_uuid(), lead_id uuid references public.eco_leads(id), customer_id uuid references public.eco_customers(id), channel text not null, external_thread_id text, assigned_employee_id uuid references public.eco_employees(id), status text not null default 'OPEN', opened_at timestamptz not null default now(), closed_at timestamptz, check(lead_id is not null or customer_id is not null));
create table public.eco_conversation_messages (id uuid primary key default gen_random_uuid(), conversation_id uuid not null references public.eco_conversations(id) on delete cascade, direction text not null check(direction in('INBOUND','OUTBOUND')), external_message_id text, body text, sent_at timestamptz not null, actor_id uuid references public.eco_employees(id), unique(conversation_id,external_message_id));
create table public.eco_touchpoints (id uuid primary key default gen_random_uuid(), lead_id uuid references public.eco_leads(id), customer_id uuid references public.eco_customers(id), campaign_id uuid references public.eco_campaigns(id), channel text not null, occurred_at timestamptz not null, metadata jsonb not null default '{}');
create table public.eco_attribution_results (id uuid primary key default gen_random_uuid(), customer_id uuid not null references public.eco_customers(id), model_version text not null, campaign_id uuid references public.eco_campaigns(id), channel text not null, weight numeric(8,6) not null check(weight between 0 and 1), calculated_at timestamptz not null default now());
create table public.eco_sales_tasks (id uuid primary key default gen_random_uuid(), lead_id uuid references public.eco_leads(id), customer_id uuid references public.eco_customers(id), assigned_employee_id uuid not null references public.eco_employees(id), task_type text not null, title text not null, due_at timestamptz not null, priority text not null default 'NORMAL', status text not null default 'OPEN', outcome text, completed_at timestamptz, created_at timestamptz not null default now(), is_demo boolean not null default false);

create table public.eco_meal_slots (code text primary key, name_ar text not null, sort_order integer not null);
insert into public.eco_meal_slots values('BREAKFAST','فطار',1),('LUNCH','غداء',2),('DINNER','عشاء',3),('SNACK','Snack',4) on conflict(code) do update set name_ar=excluded.name_ar,sort_order=excluded.sort_order;
create table public.eco_meals (id uuid primary key default gen_random_uuid(), branch_id uuid not null references public.eco_branches(id), code text not null, name_ar text not null, slot_code text not null references public.eco_meal_slots(code), active boolean not null default true, created_at timestamptz not null default now(), unique(branch_id,code));
create table public.eco_meal_versions (id uuid primary key default gen_random_uuid(), meal_id uuid not null references public.eco_meals(id), version_number integer not null, effective_from date not null, effective_to date, status text not null default 'DRAFT', standard_cost numeric(14,4) not null default 0, allergens text[] not null default '{}', portion_spec jsonb not null default '{}', approved_by uuid references public.eco_employees(id), approved_at timestamptz, unique(meal_id,version_number));
create table public.eco_packages (id uuid primary key default gen_random_uuid(), branch_id uuid not null references public.eco_branches(id), code text not null, name_ar text not null, sale_category text not null check(sale_category in('SUBSCRIPTION','A_LA_CARTE','CORPORATE')), active boolean not null default true, unique(branch_id,code));
create table public.eco_package_versions (
  id uuid primary key default gen_random_uuid(), package_id uuid not null references public.eco_packages(id), version_number integer not null, size_code text not null,
  service_days integer not null check(service_days>0), frequency_policy text not null check(frequency_policy in('DAILY','WEEKLY','CUSTOM')),
  friday_policy text not null default 'SKIP' check(friday_policy in('SKIP','THURSDAY_DOUBLE','DELIVER')), far_zone_policy text not null default 'ALLOW' check(far_zone_policy in('ALLOW','WEEKLY_ONLY','DISALLOW')),
  start_date_rule jsonb not null default '{}', pause_policy jsonb not null default '{}', skip_policy jsonb not null default '{}', swap_policy jsonb not null default '{}', renewal_policy jsonb not null default '{}', cancellation_policy jsonb not null default '{}',
  effective_from date not null, effective_to date, status text not null default 'DRAFT' check(status in('DRAFT','APPROVED','RETIRED')), approved_by uuid references public.eco_employees(id), approved_at timestamptz, unique(package_id,version_number,size_code)
);
create table public.eco_package_slots (id uuid primary key default gen_random_uuid(), package_version_id uuid not null references public.eco_package_versions(id) on delete cascade, slot_code text not null references public.eco_meal_slots(code), quantity numeric(10,3) not null check(quantity>0), obligation_weight numeric(10,6) not null default 1 check(obligation_weight>0), unique(package_version_id,slot_code));
create table public.eco_price_books (id uuid primary key default gen_random_uuid(), branch_id uuid not null references public.eco_branches(id), code text not null, name text not null, currency char(3) not null default 'EGP', effective_from date not null, effective_to date, status text not null default 'DRAFT', approved_by uuid references public.eco_employees(id), approved_at timestamptz, unique(branch_id,code,effective_from));
create table public.eco_price_book_items (id uuid primary key default gen_random_uuid(), price_book_id uuid not null references public.eco_price_books(id), package_version_id uuid not null references public.eco_package_versions(id), unit_price numeric(14,2) not null check(unit_price>=0), tax_rate numeric(8,4) not null default 0, delivery_fee_policy jsonb not null default '{}', unique(price_book_id,package_version_id));
create table public.eco_promotions (id uuid primary key default gen_random_uuid(), code text not null unique, name text not null, discount_type text not null check(discount_type in('PERCENT','FIXED')), discount_value numeric(14,4) not null, max_discount numeric(14,2), starts_at timestamptz not null, ends_at timestamptz, eligible_categories text[] not null default '{}', approval_status text not null default 'DRAFT', usage_limit integer, active boolean not null default false);
create table public.eco_menu_months (id uuid primary key default gen_random_uuid(), branch_id uuid not null references public.eco_branches(id), month_start date not null check(extract(day from month_start)=1), status text not null default 'DRAFT', locked_at timestamptz, locked_by uuid references public.eco_employees(id), unique(branch_id,month_start));
create table public.eco_menu_days (id uuid primary key default gen_random_uuid(), menu_month_id uuid not null references public.eco_menu_months(id) on delete cascade, service_date date not null, slot_code text not null references public.eco_meal_slots(code), meal_version_id uuid not null references public.eco_meal_versions(id), quantity numeric(10,3) not null default 1 check(quantity>0), notes text, updated_by uuid references public.eco_employees(id), updated_at timestamptz not null default now(), unique(menu_month_id,service_date,slot_code));
create table public.eco_planning_exceptions (id uuid primary key default gen_random_uuid(), exception_type text not null, service_date date, subscription_id uuid, entity_type text, entity_id uuid, severity text not null default 'HIGH', description text not null, status text not null default 'OPEN', assigned_employee_id uuid references public.eco_employees(id), resolved_at timestamptz, created_at timestamptz not null default now());

create sequence public.eco_order_number_seq start 1000;
create sequence public.eco_invoice_number_seq start 1000;
create table public.eco_orders (
  id uuid primary key default gen_random_uuid(), branch_id uuid not null references public.eco_branches(id), order_number text not null unique default('ECO-'||to_char(current_date,'YYMM')||'-'||lpad(nextval('public.eco_order_number_seq')::text,6,'0')),
  customer_id uuid not null references public.eco_customers(id), lead_id uuid references public.eco_leads(id), order_type text not null check(order_type in('SUBSCRIPTION','A_LA_CARTE','RENEWAL','REACTIVATION','CORPORATE')),
  status text not null default 'PENDING_PAYMENT' check(status in('DRAFT','PENDING_PAYMENT','PENDING_VERIFICATION','CONFIRMED','ON_HOLD','CANCELED','COMPLETED')),
  sales_owner_id uuid not null references public.eco_employees(id), service_start_date date not null, address_id uuid not null references public.eco_customer_addresses(id), delivery_window_id uuid not null references public.eco_delivery_windows(id),
  notes text, confirmed_at timestamptz, canceled_at timestamptz, created_by uuid not null references public.eco_employees(id), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), is_demo boolean not null default false
);
create table public.eco_order_lines (id uuid primary key default gen_random_uuid(), order_id uuid not null references public.eco_orders(id) on delete restrict, line_no integer not null, package_version_id uuid references public.eco_package_versions(id), meal_version_id uuid references public.eco_meal_versions(id), description text not null, quantity numeric(12,3) not null check(quantity>0), unit_price numeric(14,2) not null check(unit_price>=0), discount_amount numeric(14,2) not null default 0 check(discount_amount>=0), tax_rate numeric(8,4) not null default 0, delivery_fee numeric(14,2) not null default 0, line_total numeric(14,2) not null, source_price_book_item_id uuid references public.eco_price_book_items(id), unique(order_id,line_no));
create table public.eco_invoices (
  id uuid primary key default gen_random_uuid(), branch_id uuid not null references public.eco_branches(id), order_id uuid not null unique references public.eco_orders(id), customer_id uuid not null references public.eco_customers(id),
  invoice_number text not null unique default('INV-'||to_char(current_date,'YYMM')||'-'||lpad(nextval('public.eco_invoice_number_seq')::text,6,'0')), issue_date date not null default current_date, due_date date not null default current_date,
  currency char(3) not null default 'EGP', subtotal numeric(14,2) not null, discount_total numeric(14,2) not null default 0, delivery_fees numeric(14,2) not null default 0, tax_total numeric(14,2) not null default 0, total numeric(14,2) not null,
  status text not null default 'OPEN' check(status in('OPEN','PARTIALLY_PAID','PAID','VOID','REFUNDED')), immutable_snapshot jsonb not null, snapshot_sha256 text not null, created_at timestamptz not null default now(), paid_at timestamptz, is_demo boolean not null default false,
  check(total=subtotal-discount_total+delivery_fees+tax_total)
);
create table public.eco_invoice_lines (id uuid primary key default gen_random_uuid(), invoice_id uuid not null references public.eco_invoices(id) on delete restrict, line_no integer not null, description text not null, quantity numeric(12,3) not null, unit_price numeric(14,2) not null, discount_amount numeric(14,2) not null default 0, tax_amount numeric(14,2) not null default 0, line_total numeric(14,2) not null, performance_obligation_type text not null, obligation_weight numeric(10,6) not null default 1, source_order_line_id uuid not null unique references public.eco_order_lines(id), unique(invoice_id,line_no));
create table public.eco_bank_accounts (id uuid primary key default gen_random_uuid(), branch_id uuid not null references public.eco_branches(id), code text not null, name text not null, account_type text not null, currency char(3) not null default 'EGP', masked_account text, active boolean not null default true, unique(branch_id,code));
create table public.eco_payments (
  id uuid primary key default gen_random_uuid(), customer_id uuid not null references public.eco_customers(id), invoice_id uuid not null references public.eco_invoices(id), method text not null check(method in('CASH','INSTAPAY','BANK_TRANSFER','WALLET','VISA','PAYMENT_LINK','WEBSITE_APP')),
  declared_amount numeric(14,2) not null check(declared_amount>=0), verified_amount numeric(14,2), currency char(3) not null default 'EGP', status text not null default 'PENDING_VERIFICATION' check(status in('PENDING_PAYMENT','PENDING_VERIFICATION','VERIFIED','REJECTED','REVERSED')),
  reference text, destination_account_id uuid references public.eco_bank_accounts(id), payer_name text, received_at timestamptz, verified_at timestamptz, verified_by uuid references public.eco_employees(id), rejection_reason text,
  created_by uuid not null references public.eco_employees(id), created_at timestamptz not null default now(), is_demo boolean not null default false
);
create unique index eco_payments_reference_unique on public.eco_payments(method,reference) where reference is not null and status<>'REJECTED';
