-- Helper functions are replaced safely on every run. They contain their own authorization.
create or replace function public.eco_current_employee_id() returns uuid
language sql stable security definer set search_path=public,pg_temp as $$ select id from public.eco_employees where auth_user_id=auth.uid() and status='ACTIVE' limit 1 $$;

create or replace function public.eco_actor_has_permission(p_actor_id uuid,p_permission text) returns boolean
language sql stable security definer set search_path=public,pg_temp as $$
select exists(
 select 1 from public.eco_employees e join public.eco_employee_role_assignments a on a.employee_id=e.id and a.approved
 join public.eco_role_permissions rp on rp.role_code=a.role_code
 where e.id=p_actor_id and e.status='ACTIVE' and a.effective_from<=current_date and (a.effective_to is null or a.effective_to>=current_date) and rp.permission_code in(p_permission,'*')
) $$;

create or replace function public.eco_require_actor(p_actor_id uuid,p_permission text) returns void
language plpgsql stable security definer set search_path=public,pg_temp as $$ begin if not public.eco_actor_has_permission(p_actor_id,p_permission) then raise exception 'ECO_FORBIDDEN:%',p_permission using errcode='42501'; end if; end $$;

create or replace function public.eco_has_permission(p_permission text) returns boolean
language sql stable security definer set search_path=public,pg_temp as $$ select public.eco_actor_has_permission(public.eco_current_employee_id(),p_permission) $$;

create or replace function public.eco_customer_in_scope(p_customer_id uuid) returns boolean
language sql stable security definer set search_path=public,pg_temp as $$
with me as(select public.eco_current_employee_id() id), myroles as(select a.role_code from public.eco_employee_role_assignments a,me where a.employee_id=me.id and a.approved and a.effective_from<=current_date and(a.effective_to is null or a.effective_to>=current_date))
select exists(select 1 from myroles where role_code in('ceo','system_admin','finance_controller','accountant','auditor_readonly'))
or exists(select 1 from public.eco_customer_assignments ca,me where ca.customer_id=p_customer_id and ca.employee_id=me.id and ca.effective_from<=current_date and(ca.effective_to is null or ca.effective_to>=current_date))
or exists(select 1 from myroles where role_code in('sales_manager','retention_lead') and exists(select 1 from public.eco_customer_assignments ca join public.eco_team_members tm on tm.employee_id=ca.employee_id join public.eco_team_members mine on mine.team_id=tm.team_id,me where mine.employee_id=me.id and ca.customer_id=p_customer_id));
$$;

create or replace function public.eco_set_updated_at() returns trigger language plpgsql set search_path=public,pg_temp as $$ begin new.updated_at=now(); return new; end $$;
create or replace function public.eco_block_mutation() returns trigger language plpgsql set search_path=public,pg_temp as $$ begin raise exception 'ECO_IMMUTABLE:%',tg_table_name using errcode='55000'; end $$;
create or replace function public.eco_validate_journal_balance() returns trigger language plpgsql set search_path=public,pg_temp as $$ declare v_id uuid; v_debit numeric; v_credit numeric; begin v_id=coalesce(new.journal_entry_id,old.journal_entry_id); select coalesce(sum(debit),0),coalesce(sum(credit),0) into v_debit,v_credit from public.eco_journal_lines where journal_entry_id=v_id; if v_debit<>v_credit then raise exception 'ECO_UNBALANCED_JOURNAL:%:%',v_debit,v_credit using errcode='23514'; end if; return null; end $$;

drop trigger if exists eco_customers_updated_at on public.eco_customers; create trigger eco_customers_updated_at before update on public.eco_customers for each row execute function public.eco_set_updated_at();
drop trigger if exists eco_orders_updated_at on public.eco_orders; create trigger eco_orders_updated_at before update on public.eco_orders for each row execute function public.eco_set_updated_at();
drop trigger if exists eco_subscriptions_updated_at on public.eco_subscriptions; create trigger eco_subscriptions_updated_at before update on public.eco_subscriptions for each row execute function public.eco_set_updated_at();
drop trigger if exists eco_invoice_lines_immutable on public.eco_invoice_lines; create trigger eco_invoice_lines_immutable before update or delete on public.eco_invoice_lines for each row execute function public.eco_block_mutation();
drop trigger if exists eco_entitlement_ledger_immutable on public.eco_entitlement_ledger; create trigger eco_entitlement_ledger_immutable before update or delete on public.eco_entitlement_ledger for each row execute function public.eco_block_mutation();
drop trigger if exists eco_stock_movements_immutable on public.eco_stock_movements; create trigger eco_stock_movements_immutable before update or delete on public.eco_stock_movements for each row execute function public.eco_block_mutation();
drop trigger if exists eco_audit_events_immutable on public.eco_audit_events; create trigger eco_audit_events_immutable before update or delete on public.eco_audit_events for each row execute function public.eco_block_mutation();
drop trigger if exists eco_journal_balance on public.eco_journal_lines; create constraint trigger eco_journal_balance after insert or update or delete on public.eco_journal_lines deferrable initially deferred for each row execute function public.eco_validate_journal_balance();

create or replace function public.eco_begin_idempotent(p_operation text,p_key text,p_actor_id uuid,p_payload jsonb) returns jsonb
language plpgsql security definer set search_path=public,extensions,pg_temp as $$ declare v_row public.eco_idempotency_keys%rowtype; v_hash text:=encode(digest(p_payload::text,'sha256'),'hex'); begin
 select * into v_row from public.eco_idempotency_keys where operation=p_operation and idempotency_key=p_key for update;
 if found then if v_row.request_hash<>v_hash then raise exception 'ECO_IDEMPOTENCY_PAYLOAD_MISMATCH' using errcode='23505'; end if; if v_row.status='COMPLETED' then return v_row.response_snapshot; end if; raise exception 'ECO_IDEMPOTENCY_IN_PROGRESS' using errcode='55P03'; end if;
 insert into public.eco_idempotency_keys(operation,idempotency_key,actor_id,request_hash) values(p_operation,p_key,p_actor_id,v_hash); return null;
end $$;
create or replace function public.eco_finish_idempotent(p_operation text,p_key text,p_response jsonb) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$ begin update public.eco_idempotency_keys set status='COMPLETED',response_snapshot=p_response,completed_at=now() where operation=p_operation and idempotency_key=p_key; return p_response; end $$;

create or replace function public.eco_bootstrap_first_admin(p_auth_user_id uuid,p_email text,p_full_name text,p_secret_fingerprint text) returns jsonb
language plpgsql security definer set search_path=public,extensions,pg_temp as $$ declare v_org uuid;v_branch uuid;v_emp uuid; begin
 if exists(select 1 from public.eco_employees) then raise exception 'ECO_BOOTSTRAP_ALREADY_COMPLETED' using errcode='23505'; end if;
 insert into public.eco_organizations(legal_name,trade_name) values('ECO Healthy','ECO Healthy') returning id into v_org;
 insert into public.eco_branches(organization_id,code,name) values(v_org,'CAIRO','Cairo Kitchen') returning id into v_branch;
 insert into public.eco_employees(organization_id,auth_user_id,employee_number,full_name,email,status,hired_at) values(v_org,p_auth_user_id,'ECO-0001',p_full_name,lower(p_email),'ACTIVE',current_date) returning id into v_emp;
 insert into public.eco_employee_role_assignments(employee_id,role_code,effective_from,approved,approved_by,approved_at,created_by) values(v_emp,'system_admin',current_date,true,v_emp,now(),v_emp),(v_emp,'ceo',current_date,true,v_emp,now(),v_emp);
 insert into public.eco_audit_events(actor_id,action,entity_type,entity_id,source,reason,event_hash) values(v_emp,'BOOTSTRAP_FIRST_ADMIN','employee',v_emp::text,'SERVER',p_secret_fingerprint,encode(digest(v_emp::text||clock_timestamp()::text,'sha256'),'hex'));
 return jsonb_build_object('employee_id',v_emp,'branch_id',v_branch,'message','تم إنشاء الإدارة الأولى. فعّل MFA قبل الاستخدام.');
end $$;

create or replace function public.eco_create_employee_invitation(p_actor_id uuid,p_auth_user_id uuid,p_payload jsonb) returns jsonb
language plpgsql security definer set search_path=public,pg_temp as $$ declare v_org uuid;v_emp uuid;v_role text; begin
 perform public.eco_require_actor(p_actor_id,'employees.invite'); select organization_id into v_org from public.eco_employees where id=p_actor_id;
 insert into public.eco_employees(organization_id,auth_user_id,employee_number,full_name,email,status) values(v_org,p_auth_user_id,'ECO-'||lpad((1000+floor(random()*8999))::int::text,4,'0'),p_payload->>'fullName',lower(p_payload->>'email'),'INVITED') returning id into v_emp;
 insert into public.eco_employee_invitations(employee_id,invited_email,auth_user_id,invited_by) values(v_emp,lower(p_payload->>'email'),p_auth_user_id,p_actor_id);
 for v_role in select jsonb_array_elements_text(p_payload->'roleCodes') loop insert into public.eco_employee_role_assignments(employee_id,role_code,effective_from,approved,approved_by,approved_at,created_by) values(v_emp,v_role,current_date,true,p_actor_id,now(),p_actor_id); end loop;
 return jsonb_build_object('employee_id',v_emp,'status','INVITED');
end $$;

create or replace function public.eco_link_invited_user() returns trigger language plpgsql security definer set search_path=public,auth,pg_temp as $$ begin
 update public.eco_employees set auth_user_id=new.id,status='ACTIVE',updated_at=now() where lower(email)=lower(new.email) and status='INVITED' and auth_user_id in(new.id,null);
 update public.eco_employee_invitations set accepted_at=now(),auth_user_id=new.id where lower(invited_email)=lower(new.email) and revoked_at is null and expires_at>now(); return new;
end $$;
drop trigger if exists eco_on_auth_user_created on auth.users; create trigger eco_on_auth_user_created after insert on auth.users for each row execute function public.eco_link_invited_user();

create or replace function public.eco_create_customer(p_actor_id uuid,p_payload jsonb) returns jsonb
language plpgsql security definer set search_path=public,pg_temp as $$ declare v_org uuid;v_customer uuid;v_address uuid;v_phone text;v_owner uuid; begin
 perform public.eco_require_actor(p_actor_id,'customers.create'); select organization_id into v_org from public.eco_employees where id=p_actor_id; v_phone:=regexp_replace(p_payload->>'phone','[^0-9+]','','g'); v_owner:=coalesce(nullif(p_payload->>'sales_owner_id','')::uuid,p_actor_id);
 insert into public.eco_customers(organization_id,customer_number,full_name,normalized_phone,phone_display,email,created_by) values(v_org,'CUS-'||lpad(nextval('public.eco_customer_number_seq')::text,7,'0'),p_payload->>'full_name',v_phone,p_payload->>'phone',nullif(p_payload->>'email',''),p_actor_id) returning id into v_customer;
 insert into public.eco_customer_addresses(customer_id,address_line,zone_id) values(v_customer,p_payload->>'address_line',(p_payload->>'zone_id')::uuid) returning id into v_address;
 insert into public.eco_customer_assignments(customer_id,employee_id,assignment_type,effective_from,assigned_by) values(v_customer,v_owner,'SALES_OWNER',current_date,p_actor_id);
 if nullif(p_payload->>'dietary_notes','') is not null then insert into public.eco_customer_dietary_rules(customer_id,rule_type,description,created_by) values(v_customer,'NOTE',p_payload->>'dietary_notes',p_actor_id); end if;
 insert into public.eco_customer_timeline(customer_id,event_type,entity_type,entity_id,summary,actor_id) values(v_customer,'CUSTOMER_CREATED','customer',v_customer,'تم إنشاء ملف العميل',p_actor_id);
 return jsonb_build_object('customer_id',v_customer,'address_id',v_address);
end $$;

create or replace function public.eco_create_priced_invoice(p_actor_id uuid,p_payload jsonb) returns jsonb
language plpgsql security definer set search_path=public,extensions,pg_temp as $$
declare v_cached jsonb;v_key text:=p_payload->>'idempotency_key';v_customer public.eco_customers%rowtype;v_address public.eco_customer_addresses%rowtype;v_item record;v_order uuid;v_line uuid;v_invoice uuid;v_payment uuid;v_subtotal numeric(14,2);v_discount numeric(14,2):=0;v_tax numeric(14,2);v_delivery numeric(14,2);v_total numeric(14,2);v_status text;v_branch uuid;v_snapshot jsonb; begin
 perform public.eco_require_actor(p_actor_id,'orders.create'); v_cached:=public.eco_begin_idempotent('CREATE_INVOICE',v_key,p_actor_id,p_payload); if v_cached is not null then return v_cached; end if;
 select * into strict v_customer from public.eco_customers where id=(p_payload->>'customer_id')::uuid and status='ACTIVE'; if not public.eco_customer_in_scope(v_customer.id) and not public.eco_actor_has_permission(p_actor_id,'*') then raise exception 'ECO_CUSTOMER_OUT_OF_SCOPE' using errcode='42501'; end if;
 select * into strict v_address from public.eco_customer_addresses where id=(p_payload->>'address_id')::uuid and customer_id=v_customer.id and active;
 select pbi.*,pb.currency,pv.service_days,pv.id package_version_id,p.sale_category,p.name_ar package_name,p.branch_id into strict v_item from public.eco_price_book_items pbi join public.eco_price_books pb on pb.id=pbi.price_book_id and pb.status='APPROVED' join public.eco_package_versions pv on pv.id=pbi.package_version_id and pv.status='APPROVED' join public.eco_packages p on p.id=pv.package_id where pbi.package_version_id=(p_payload->>'package_version_id')::uuid and pb.effective_from<=current_date and(pb.effective_to is null or pb.effective_to>=current_date) order by pb.effective_from desc limit 1;
 v_branch:=v_item.branch_id;v_subtotal:=round(v_item.unit_price,2);select default_delivery_fee into v_delivery from public.eco_zones where id=v_address.zone_id;
 if nullif(p_payload->>'promotion_code','') is not null then select least(case when discount_type='PERCENT' then v_subtotal*discount_value/100 else discount_value end,coalesce(max_discount,v_subtotal)) into v_discount from public.eco_promotions where code=p_payload->>'promotion_code' and active and approval_status='APPROVED' and starts_at<=now() and(ends_at is null or ends_at>=now());v_discount:=coalesce(v_discount,0);end if;
 v_tax:=round((v_subtotal-v_discount)*v_item.tax_rate/100,2);v_total:=v_subtotal-v_discount+v_delivery+v_tax;v_status:=case when p_payload->>'payment_method'='CASH' then 'PENDING_PAYMENT' else 'PENDING_VERIFICATION' end;
 insert into public.eco_orders(branch_id,customer_id,order_type,status,sales_owner_id,service_start_date,address_id,delivery_window_id,notes,created_by) values(v_branch,v_customer.id,p_payload->>'order_type',v_status,p_actor_id,(p_payload->>'start_date')::date,v_address.id,(p_payload->>'delivery_window_id')::uuid,p_payload->>'notes',p_actor_id) returning id into v_order;
 insert into public.eco_order_lines(order_id,line_no,package_version_id,description,quantity,unit_price,discount_amount,tax_rate,delivery_fee,line_total,source_price_book_item_id) values(v_order,1,v_item.package_version_id,v_item.package_name,1,v_subtotal,v_discount,v_item.tax_rate,v_delivery,v_total,v_item.id) returning id into v_line;
 v_snapshot:=jsonb_build_object('order_id',v_order,'customer_id',v_customer.id,'line',jsonb_build_object('description',v_item.package_name,'package_version_id',v_item.package_version_id,'unit_price',v_subtotal,'discount',v_discount,'tax',v_tax,'delivery',v_delivery),'total',v_total,'created_at',now());
 insert into public.eco_invoices(branch_id,order_id,customer_id,currency,subtotal,discount_total,delivery_fees,tax_total,total,status,immutable_snapshot,snapshot_sha256) values(v_branch,v_order,v_customer.id,v_item.currency,v_subtotal,v_discount,v_delivery,v_tax,v_total,'OPEN',v_snapshot,encode(digest(v_snapshot::text,'sha256'),'hex')) returning id into v_invoice;
 insert into public.eco_invoice_lines(invoice_id,line_no,description,quantity,unit_price,discount_amount,tax_amount,line_total,performance_obligation_type,obligation_weight,source_order_line_id) values(v_invoice,1,v_item.package_name,1,v_subtotal,v_discount,v_tax,v_total-v_delivery,v_item.sale_category,1,v_line);
 insert into public.eco_payments(customer_id,invoice_id,method,declared_amount,currency,status,reference,created_by) values(v_customer.id,v_invoice,p_payload->>'payment_method',v_total,v_item.currency,v_status,nullif(p_payload->>'payment_reference',''),p_actor_id) returning id into v_payment;
 insert into public.eco_outbox_events(event_type,aggregate_type,aggregate_id,payload) values('INVOICE_CREATED','invoice',v_invoice::text,jsonb_build_object('invoice_id',v_invoice,'payment_id',v_payment,'status',v_status));
 return public.eco_finish_idempotent('CREATE_INVOICE',v_key,jsonb_build_object('order_id',v_order,'invoice_id',v_invoice,'payment_id',v_payment,'total',v_total,'status',v_status));
end $$;

create or replace function public.eco_confirm_payment(p_actor_id uuid,p_payload jsonb) returns jsonb
language plpgsql security definer set search_path=public,pg_temp as $$
declare v_cached jsonb;v_key text:=p_payload->>'idempotency_key';v_payment public.eco_payments%rowtype;v_invoice public.eco_invoices%rowtype;v_order public.eco_orders%rowtype;v_allocated numeric(14,2);v_subscription uuid;v_cycle uuid;v_plan uuid;v_slot record;v_day integer;v_cursor date;v_menu uuid;v_entitlement uuid;v_period date;v_result jsonb; begin
 perform public.eco_require_actor(p_actor_id,'payments.verify');v_cached:=public.eco_begin_idempotent('CONFIRM_PAYMENT',v_key,p_actor_id,p_payload);if v_cached is not null then return v_cached;end if;
 select * into strict v_payment from public.eco_payments where id=(p_payload->>'payment_id')::uuid for update;if v_payment.status='VERIFIED' then return public.eco_finish_idempotent('CONFIRM_PAYMENT',v_key,jsonb_build_object('payment_id',v_payment.id,'duplicate',true));end if;
 select * into strict v_invoice from public.eco_invoices where id=v_payment.invoice_id for update;select * into strict v_order from public.eco_orders where id=v_invoice.order_id for update;
 if v_payment.method<>'CASH' and not exists(select 1 from public.eco_payment_proofs where invoice_id=v_invoice.id and status in('UPLOADED','VERIFIED')) then raise exception 'ECO_PAYMENT_PROOF_REQUIRED' using errcode='23514';end if;
 if exists(select 1 from public.eco_payments where id<>v_payment.id and method=v_payment.method and reference=p_payload->>'reference' and status='VERIFIED') then raise exception 'ECO_DUPLICATE_PAYMENT_REFERENCE' using errcode='23505';end if;
 update public.eco_payments set verified_amount=(p_payload->>'amount_received')::numeric,currency=p_payload->>'currency',destination_account_id=(p_payload->>'account_id')::uuid,reference=p_payload->>'reference',payer_name=p_payload->>'payer',received_at=(p_payload->>'receipt_date')::date,verified_at=now(),verified_by=p_actor_id,status='VERIFIED' where id=v_payment.id;
 insert into public.eco_payment_allocations(payment_id,invoice_id,amount,actor_id) values(v_payment.id,v_invoice.id,least((p_payload->>'amount_received')::numeric,v_invoice.total),p_actor_id) on conflict(payment_id,invoice_id) do nothing;
 select coalesce(sum(amount),0) into v_allocated from public.eco_payment_allocations where invoice_id=v_invoice.id;
 update public.eco_invoices set status=case when v_allocated>=total then 'PAID' else 'PARTIALLY_PAID' end,paid_at=case when v_allocated>=total then now() else null end where id=v_invoice.id;
 if v_allocated<v_invoice.total then return public.eco_finish_idempotent('CONFIRM_PAYMENT',v_key,jsonb_build_object('payment_id',v_payment.id,'invoice_status','PARTIALLY_PAID','activated',false));end if;
 update public.eco_orders set status='CONFIRMED',confirmed_at=coalesce(confirmed_at,now()) where id=v_order.id;
 if v_order.order_type in('SUBSCRIPTION','RENEWAL','REACTIVATION') then
   insert into public.eco_subscriptions(order_id,customer_id,package_version_id,sales_owner_id,start_date,status) select v_order.id,v_order.customer_id,ol.package_version_id,v_order.sales_owner_id,v_order.service_start_date,'ACTIVE' from public.eco_order_lines ol where ol.order_id=v_order.id limit 1 on conflict(order_id) do update set updated_at=public.eco_subscriptions.updated_at returning id into v_subscription;
   if v_subscription is null then select id into v_subscription from public.eco_subscriptions where order_id=v_order.id;end if;
   insert into public.eco_subscription_cycles(subscription_id,cycle_number,start_date,status,source_invoice_id) values(v_subscription,1,v_order.service_start_date,'ACTIVE',v_invoice.id) on conflict(subscription_id,cycle_number) do update set source_invoice_id=excluded.source_invoice_id returning id into v_cycle;
   update public.eco_subscriptions set current_cycle_id=v_cycle where id=v_subscription;
   for v_slot in select ps.slot_code,ps.quantity,pv.service_days,ps.obligation_weight from public.eco_package_slots ps join public.eco_package_versions pv on pv.id=ps.package_version_id join public.eco_subscriptions s on s.package_version_id=pv.id where s.id=v_subscription loop
     insert into public.eco_entitlements(cycle_id,subscription_id,slot_code,granted_quantity,obligation_unit_value) values(v_cycle,v_subscription,v_slot.slot_code,v_slot.quantity*v_slot.service_days,(v_invoice.total-v_invoice.delivery_fees)*v_slot.obligation_weight/(v_slot.quantity*v_slot.service_days)) on conflict(cycle_id,slot_code) do update set granted_quantity=excluded.granted_quantity returning id into v_entitlement;
     insert into public.eco_entitlement_ledger(entitlement_id,event_type,quantity,unit_value,source_type,source_id,idempotency_key,actor_id) values(v_entitlement,'GRANT',v_slot.quantity,(v_invoice.total-v_invoice.delivery_fees)*v_slot.obligation_weight,'invoice',v_invoice.id,'grant:'||v_entitlement,p_actor_id) on conflict(idempotency_key) do nothing;
   end loop;
   v_cursor:=v_order.service_start_date;v_day:=0;while v_day<(select service_days from public.eco_package_versions where id=(select package_version_id from public.eco_subscriptions where id=v_subscription)) loop
     if extract(dow from v_cursor)<>5 then v_day:=v_day+1;for v_slot in select e.id entitlement_id,e.slot_code,ps.quantity from public.eco_entitlements e join public.eco_package_slots ps on ps.package_version_id=(select package_version_id from public.eco_subscriptions where id=v_subscription) and ps.slot_code=e.slot_code where e.subscription_id=v_subscription loop
       select md.meal_version_id into v_menu from public.eco_menu_days md join public.eco_menu_months mm on mm.id=md.menu_month_id where md.service_date=v_cursor and md.slot_code=v_slot.slot_code and mm.branch_id=v_order.branch_id limit 1;
       if v_menu is null then insert into public.eco_planning_exceptions(exception_type,service_date,subscription_id,entity_type,entity_id,description) values('MISSING_MENU',v_cursor,v_subscription,'subscription',v_subscription,'لا توجد وجبة معتمدة لهذا اليوم والـslot') on conflict do nothing;
       else insert into public.eco_fulfillments(subscription_id,order_id,customer_id,entitlement_id,service_date,delivery_date,slot_code,meal_version_id,quantity,size_code,address_id,delivery_window_id,status,source_type,source_id) values(v_subscription,v_order.id,v_order.customer_id,v_slot.entitlement_id,v_cursor,v_cursor,v_slot.slot_code,v_menu,v_slot.quantity,(select size_code from public.eco_package_versions where id=(select package_version_id from public.eco_subscriptions where id=v_subscription)),v_order.address_id,v_order.delivery_window_id,'READY_FOR_KITCHEN','cycle',v_cycle) on conflict do nothing;end if;
     end loop;end if;v_cursor:=v_cursor+1;end loop;update public.eco_subscriptions set expected_end_date=v_cursor-1,renewal_due_date=v_cursor-8 where id=v_subscription;update public.eco_subscription_cycles set expected_end_date=v_cursor-1,renewal_due_date=v_cursor-8 where id=v_cycle;
 end if;
 select cpv.id into v_plan from public.eco_commission_plan_versions cpv where cpv.status='APPROVED' and cpv.effective_from<=current_date and(cpv.effective_to is null or cpv.effective_to>=current_date) and v_order.order_type=any(cpv.eligible_sales_types) order by cpv.version_number desc limit 1;v_period:=date_trunc('month',current_date)::date;
 insert into public.eco_sales_credit_events(employee_id,customer_id,order_id,invoice_id,event_type,lifecycle_state,booked_value,commissionable_value,period_start,maturity_earliest_at,maturity_reason,plan_version_id,idempotency_key) values(v_order.sales_owner_id,v_order.customer_id,v_order.id,v_invoice.id,'PAYMENT_VERIFIED','PAYMENT_VERIFIED_PENDING_MATURITY',v_invoice.total,v_invoice.subtotal-v_invoice.discount_total,v_period,now()+coalesce((select fixed_maturity_days from public.eco_commission_plan_versions where id=v_plan),15)*interval '1 day','بانتظار شروط الاستحقاق: مدة الاحتفاظ ونسبة تنفيذ الاشتراك',v_plan,'credit:'||v_invoice.id) on conflict(invoice_id,event_type) do nothing;
 insert into public.eco_outbox_events(event_type,aggregate_type,aggregate_id,payload) values('PAYMENT_CONFIRMED','invoice',v_invoice.id::text,jsonb_build_object('invoice_id',v_invoice.id,'subscription_id',v_subscription)) on conflict do nothing;
 v_result:=jsonb_build_object('payment_id',v_payment.id,'invoice_id',v_invoice.id,'order_id',v_order.id,'subscription_id',v_subscription,'activated',true);return public.eco_finish_idempotent('CONFIRM_PAYMENT',v_key,v_result);
end $$;

create or replace function public.eco_reject_payment(p_actor_id uuid,p_payload jsonb) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$ declare v_cached jsonb;v_key text:=p_payload->>'idempotency_key';v_id uuid:=(p_payload->>'payment_id')::uuid;begin perform public.eco_require_actor(p_actor_id,'payments.verify');v_cached:=public.eco_begin_idempotent('REJECT_PAYMENT',v_key,p_actor_id,p_payload);if v_cached is not null then return v_cached;end if;update public.eco_payments set status='REJECTED',rejection_reason=p_payload->>'reason',verified_by=p_actor_id,verified_at=now() where id=v_id and status<>'VERIFIED';if not found then raise exception 'ECO_PAYMENT_CANNOT_REJECT';end if;return public.eco_finish_idempotent('REJECT_PAYMENT',v_key,jsonb_build_object('payment_id',v_id,'status','REJECTED'));end $$;

create or replace function public.eco_preview_subscription_change(p_actor_id uuid,p_payload jsonb) returns jsonb
language plpgsql security definer set search_path=public,pg_temp as $$ declare v_sub public.eco_subscriptions%rowtype;v_affected integer;v_shift integer:=0;v_new_end date;v_preview jsonb;begin
 perform public.eco_require_actor(p_actor_id,'subscriptions.change.preview');select * into strict v_sub from public.eco_subscriptions where id=(p_payload->>'subscription_id')::uuid;
 if not public.eco_customer_in_scope(v_sub.customer_id) and not public.eco_actor_has_permission(p_actor_id,'subscriptions.change.commit') then raise exception 'ECO_SUBSCRIPTION_OUT_OF_SCOPE' using errcode='42501';end if;
 select count(*) into v_affected from public.eco_fulfillments where subscription_id=v_sub.id and service_date>=(p_payload->>'effective_from')::date and status in('PLANNED','READY_FOR_KITCHEN');
 if p_payload->>'change_type'='PAUSE' and nullif(p_payload->>'effective_to','') is not null then v_shift:=greatest(0,(p_payload->>'effective_to')::date-(p_payload->>'effective_from')::date+1);end if;v_new_end:=v_sub.expected_end_date+v_shift;
 v_preview:=jsonb_build_object('subscription_id',v_sub.id,'change_type',p_payload->>'change_type','current_expected_end_date',v_sub.expected_end_date,'new_expected_end_date',v_new_end,'affected_fulfillments',v_affected,'financial_effect',0,'kitchen_cutoff_warning',exists(select 1 from public.eco_fulfillments where subscription_id=v_sub.id and service_date<=current_date+1 and service_date>=(p_payload->>'effective_from')::date and locked_at is not null),'requires_approval',p_payload->>'change_type' in('CANCEL','UPGRADE','DOWNGRADE'));
 return v_preview;
end $$;

create or replace function public.eco_commit_subscription_change(p_actor_id uuid,p_payload jsonb) returns jsonb
language plpgsql security definer set search_path=public,pg_temp as $$ declare v_cached jsonb;v_key text:=p_payload->>'idempotency_key';v_preview jsonb;v_request uuid;v_sub public.eco_subscriptions%rowtype;v_shift integer:=0;v_type text:=p_payload->>'change_type';begin
 perform public.eco_require_actor(p_actor_id,'subscriptions.change.commit');v_cached:=public.eco_begin_idempotent('SUBSCRIPTION_CHANGE',v_key,p_actor_id,p_payload);if v_cached is not null then return v_cached;end if;select * into strict v_sub from public.eco_subscriptions where id=(p_payload->>'subscription_id')::uuid for update;v_preview:=public.eco_preview_subscription_change(p_actor_id,p_payload);
 insert into public.eco_subscription_change_requests(subscription_id,change_type,requested_payload,preview_snapshot,status,requested_by,approved_by,approved_at,committed_at,idempotency_key,reason) values(v_sub.id,v_type,p_payload,v_preview,'COMMITTED',p_actor_id,p_actor_id,now(),now(),v_key,p_payload->>'reason') returning id into v_request;
 if v_type='PAUSE' then insert into public.eco_subscription_pauses(subscription_id,change_request_id,starts_on,ends_on) values(v_sub.id,v_request,(p_payload->>'effective_from')::date,nullif(p_payload->>'effective_to','')::date);update public.eco_subscriptions set status='PAUSED' where id=v_sub.id;update public.eco_fulfillments set status='PLANNED',locked_at=null where subscription_id=v_sub.id and service_date>=(p_payload->>'effective_from')::date and(nullif(p_payload->>'effective_to','') is null or service_date<=(p_payload->>'effective_to')::date) and status='READY_FOR_KITCHEN';if nullif(p_payload->>'effective_to','') is not null then v_shift:=(p_payload->>'effective_to')::date-(p_payload->>'effective_from')::date+1;update public.eco_fulfillments set service_date=service_date+v_shift,delivery_date=delivery_date+v_shift where subscription_id=v_sub.id and service_date>=(p_payload->>'effective_from')::date and status in('PLANNED','READY_FOR_KITCHEN');update public.eco_subscriptions set expected_end_date=expected_end_date+v_shift,renewal_due_date=renewal_due_date+v_shift where id=v_sub.id;end if;
 elsif v_type='RESUME' then update public.eco_subscriptions set status='ACTIVE' where id=v_sub.id;update public.eco_subscription_pauses set status='RESUMED',auto_resumed_at=now() where subscription_id=v_sub.id and status='ACTIVE';
 elsif v_type='SKIP' then update public.eco_fulfillments set status='SKIPPED' where subscription_id=v_sub.id and service_date=(p_payload->>'effective_from')::date and status in('PLANNED','READY_FOR_KITCHEN');
 elsif v_type='CANCEL' then update public.eco_subscriptions set status='CANCELED',canceled_at=now() where id=v_sub.id;update public.eco_fulfillments set status='CANCELED' where subscription_id=v_sub.id and service_date>=current_date and status in('PLANNED','READY_FOR_KITCHEN');update public.eco_sales_credit_events set lifecycle_state=case when lifecycle_state='PAYMENT_VERIFIED_PENDING_MATURITY' then 'CANCELED_BEFORE_MATURITY' else 'REVERSED_AFTER_MATURITY' end where order_id=v_sub.order_id and lifecycle_state in('PAYMENT_VERIFIED_PENDING_MATURITY','ELIGIBLE_CONFIRMED');
 end if;
 insert into public.eco_subscription_events(subscription_id,event_type,effective_at,actor_id,source_type,source_id,payload,idempotency_key) values(v_sub.id,v_type,now(),p_actor_id,'change_request',v_request,p_payload,'subevent:'||v_key);
 insert into public.eco_outbox_events(event_type,aggregate_type,aggregate_id,payload) values('SUBSCRIPTION_CHANGED','subscription',v_sub.id::text,jsonb_build_object('change_type',v_type,'request_id',v_request)) on conflict do nothing;
 return public.eco_finish_idempotent('SUBSCRIPTION_CHANGE',v_key,jsonb_build_object('request_id',v_request,'preview',v_preview,'status','COMMITTED'));
end $$;

create or replace function public.eco_create_production_batch(p_actor_id uuid,p_payload jsonb) returns jsonb
language plpgsql security definer set search_path=public,pg_temp as $$ declare v_cached jsonb;v_key text:=p_payload->>'idempotency_key';v_batch uuid;v_id text;begin perform public.eco_require_actor(p_actor_id,'kitchen.batch.create');v_cached:=public.eco_begin_idempotent('CREATE_BATCH',v_key,p_actor_id,p_payload);if v_cached is not null then return v_cached;end if;insert into public.eco_production_batches(branch_id,service_date,planned_by,idempotency_key) select branch_id,(p_payload->>'service_date')::date,p_actor_id,v_key from public.eco_branches where active order by created_at limit 1 returning id into v_batch;for v_id in select jsonb_array_elements_text(p_payload->'demand_ids') loop insert into public.eco_production_batch_items(batch_id,demand_id,planned_quantity) select v_batch,id,required_quantity from public.eco_production_demand where id=v_id::uuid and service_date=(p_payload->>'service_date')::date on conflict do nothing;end loop;if not exists(select 1 from public.eco_production_batch_items where batch_id=v_batch) then raise exception 'ECO_NO_VALID_DEMAND';end if;return public.eco_finish_idempotent('CREATE_BATCH',v_key,jsonb_build_object('batch_id',v_batch));end $$;

create or replace function public.eco_release_batch_qa(p_actor_id uuid,p_payload jsonb) returns jsonb
language plpgsql security definer set search_path=public,pg_temp as $$ declare v_cached jsonb;v_key text:=p_payload->>'idempotency_key';v_batch uuid:=(p_payload->>'batch_id')::uuid;begin perform public.eco_require_actor(p_actor_id,'kitchen.qa.release');v_cached:=public.eco_begin_idempotent('QA_RELEASE',v_key,p_actor_id,p_payload);if v_cached is not null then return v_cached;end if;insert into public.eco_qa_checks(batch_id,check_type,result,temperature_c,notes,checked_by) values(v_batch,'FINAL_RELEASE',p_payload->>'result',(p_payload->>'temperature_c')::numeric,p_payload->>'notes',p_actor_id);update public.eco_production_batches set status=case when p_payload->>'result'='PASSED' then 'QA_RELEASED' else 'QA_HOLD' end,qa_released_at=case when p_payload->>'result'='PASSED' then now() else null end where id=v_batch and status in('PRODUCED','QA_HOLD');if not found then raise exception 'ECO_BATCH_NOT_READY_FOR_QA';end if;if p_payload->>'result'='PASSED' then update public.eco_fulfillments f set status='QA_RELEASED' from public.eco_production_batch_items bi where bi.batch_id=v_batch and f.service_date=(select service_date from public.eco_production_batches where id=v_batch) and f.meal_version_id=(select meal_version_id from public.eco_production_demand where id=bi.demand_id) and f.status in('BATCHED','PRODUCED');insert into public.eco_outbox_events(event_type,aggregate_type,aggregate_id,payload) values('BATCH_QA_RELEASED','production_batch',v_batch::text,jsonb_build_object('batch_id',v_batch)) on conflict do nothing;end if;return public.eco_finish_idempotent('QA_RELEASE',v_key,jsonb_build_object('batch_id',v_batch,'result',p_payload->>'result'));end $$;

create or replace function public.eco_create_route(p_actor_id uuid,p_payload jsonb) returns jsonb
language plpgsql security definer set search_path=public,pg_temp as $$ declare v_cached jsonb;v_key text:=p_payload->>'idempotency_key';v_route uuid;v_rider uuid;begin perform public.eco_require_actor(p_actor_id,'routes.manage');v_cached:=public.eco_begin_idempotent('CREATE_ROUTE',v_key,p_actor_id,p_payload);if v_cached is not null then return v_cached;end if;if nullif(p_payload->>'rider_employee_id','') is not null then select id into v_rider from public.eco_riders where employee_id=(p_payload->>'rider_employee_id')::uuid and active;end if;insert into public.eco_routes(branch_id,route_date,zone_id,delivery_window_id,rider_id,status,assigned_at,idempotency_key,created_by) select branch_id,(p_payload->>'route_date')::date,(p_payload->>'zone_id')::uuid,(p_payload->>'delivery_window_id')::uuid,v_rider,case when v_rider is null then 'PLANNED' else 'ASSIGNED' end,case when v_rider is null then null else now() end,v_key,p_actor_id from public.eco_zones where id=(p_payload->>'zone_id')::uuid returning id into v_route;return public.eco_finish_idempotent('CREATE_ROUTE',v_key,jsonb_build_object('route_id',v_route));end $$;

create or replace function public.eco_record_delivery_event(p_actor_id uuid,p_payload jsonb) returns jsonb
language plpgsql security definer set search_path=public,pg_temp as $$ declare v_stop public.eco_route_stops%rowtype;v_route public.eco_routes%rowtype;v_expected text;v_event text:=p_payload->>'event_type';v_ent record;begin perform public.eco_require_actor(p_actor_id,'route.own.update');if exists(select 1 from public.eco_delivery_events where client_event_id=(p_payload->>'client_event_id')::uuid) then return jsonb_build_object('duplicate',true,'client_event_id',p_payload->>'client_event_id');end if;select * into strict v_stop from public.eco_route_stops where id=(p_payload->>'route_stop_id')::uuid for update;select * into strict v_route from public.eco_routes where id=v_stop.route_id;if not exists(select 1 from public.eco_riders where id=v_route.rider_id and employee_id=p_actor_id) then raise exception 'ECO_RIDER_ROUTE_FORBIDDEN' using errcode='42501';end if;if v_stop.state='DELIVERED' then return jsonb_build_object('duplicate',true,'state','DELIVERED');end if;v_expected:=case v_event when 'ARRIVED' then 'DISPATCHED' when 'DELIVERED' then 'ARRIVED' when 'FAILED' then v_stop.state else null end;if v_event<>'FAILED' and v_stop.state<>v_expected then raise exception 'ECO_INVALID_DELIVERY_TRANSITION:%->%',v_stop.state,v_event using errcode='23514';end if;insert into public.eco_delivery_events(route_stop_id,event_type,client_event_id,device_time,actor_employee_id,latitude,longitude,metadata) values(v_stop.id,v_event,(p_payload->>'client_event_id')::uuid,(p_payload->>'device_time')::timestamptz,p_actor_id,nullif(p_payload->>'latitude','')::numeric,nullif(p_payload->>'longitude','')::numeric,p_payload);update public.eco_route_stops set state=v_event,arrived_at=case when v_event='ARRIVED' then now() else arrived_at end,delivered_at=case when v_event='DELIVERED' then now() else delivered_at end,failed_at=case when v_event='FAILED' then now() else failed_at end where id=v_stop.id;if v_event='DELIVERED' then for v_ent in select f.id fulfillment_id,f.entitlement_id,f.quantity from public.eco_stop_pack_units spu join public.eco_pack_units pu on pu.id=spu.pack_unit_id join public.eco_fulfillments f on f.id=pu.fulfillment_id where spu.route_stop_id=v_stop.id loop update public.eco_fulfillments set status='DELIVERED' where id=v_ent.fulfillment_id and status<>'DELIVERED';if found and v_ent.entitlement_id is not null then insert into public.eco_entitlement_ledger(entitlement_id,event_type,quantity,unit_value,service_date,source_type,source_id,idempotency_key,actor_id) select v_ent.entitlement_id,'CONSUME',v_ent.quantity,obligation_unit_value,current_date,'fulfillment',v_ent.fulfillment_id,'consume:'||v_ent.fulfillment_id,p_actor_id from public.eco_entitlements where id=v_ent.entitlement_id on conflict(idempotency_key) do nothing;update public.eco_entitlements set consumed_quantity=consumed_quantity+v_ent.quantity,reserved_quantity=greatest(0,reserved_quantity-v_ent.quantity) where id=v_ent.entitlement_id and not exists(select 1 from public.eco_entitlement_ledger where idempotency_key='consume:'||v_ent.fulfillment_id and occurred_at<now()-interval '1 second');end if;end loop;if v_stop.cod_amount>0 then insert into public.eco_cash_collections(route_stop_id,customer_id,expected_amount,collected_amount,state,rider_employee_id,collected_at,idempotency_key) values(v_stop.id,v_stop.customer_id,v_stop.cod_amount,coalesce(nullif(p_payload->>'cash_amount','')::numeric,0),'COLLECTED_IN_CUSTODY',p_actor_id,now(),'cash:'||v_stop.id) on conflict(route_stop_id) do nothing;end if;end if;return jsonb_build_object('route_stop_id',v_stop.id,'state',v_event,'server_received_at',now());end $$;

create or replace function public.eco_declare_rider_cash(p_actor_id uuid,p_payload jsonb) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$ declare v_route uuid:=(p_payload->>'route_id')::uuid;v_expected numeric;v_handover uuid;begin perform public.eco_require_actor(p_actor_id,'cash.rider.declare');if not exists(select 1 from public.eco_routes r join public.eco_riders rd on rd.id=r.rider_id where r.id=v_route and rd.employee_id=p_actor_id) then raise exception 'ECO_RIDER_ROUTE_FORBIDDEN' using errcode='42501';end if;select coalesce(sum(cc.collected_amount),0) into v_expected from public.eco_cash_collections cc join public.eco_route_stops rs on rs.id=cc.route_stop_id where rs.route_id=v_route;insert into public.eco_cash_handovers(route_id,rider_employee_id,expected_amount,declared_amount,difference_amount,difference_reason,state,rider_confirmed_at,idempotency_key) values(v_route,p_actor_id,v_expected,(p_payload->>'amount')::numeric,(p_payload->>'amount')::numeric-v_expected,p_payload->>'notes',case when (p_payload->>'amount')::numeric=v_expected then 'DECLARED_BY_RIDER' else 'VARIANCE_OPEN' end,now(),p_payload->>'idempotency_key') on conflict(idempotency_key) do update set declared_amount=excluded.declared_amount returning id into v_handover;update public.eco_cash_collections set state='DECLARED_BY_RIDER',declared_at=now() where route_stop_id in(select id from public.eco_route_stops where route_id=v_route);return jsonb_build_object('handover_id',v_handover,'expected',v_expected);end $$;

create or replace function public.eco_receive_cash_handover(p_actor_id uuid,p_payload jsonb) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$ declare v_id uuid:=(p_payload->>'handover_id')::uuid;v_received numeric:=(p_payload->>'amount_received')::numeric;v_expected numeric;begin perform public.eco_require_actor(p_actor_id,'cash.accounting.receive');select expected_amount into strict v_expected from public.eco_cash_handovers where id=v_id for update;update public.eco_cash_handovers set received_amount=v_received,difference_amount=v_received-v_expected,difference_reason=coalesce(p_payload->>'difference_reason',difference_reason),state=case when v_received=v_expected then 'RECEIVED_BY_ACCOUNTING' else 'VARIANCE_OPEN' end,accounting_confirmed_at=now(),accounting_employee_id=p_actor_id where id=v_id;update public.eco_cash_collections set state=case when v_received=v_expected then 'RECEIVED_BY_ACCOUNTING' else 'VARIANCE_OPEN' end where route_stop_id in(select rs.id from public.eco_route_stops rs join public.eco_cash_handovers ch on ch.route_id=rs.route_id where ch.id=v_id);return jsonb_build_object('handover_id',v_id,'difference',v_received-v_expected,'payment_verified',false);end $$;

create or replace function public.eco_save_sales_target(p_actor_id uuid,p_payload jsonb) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$ declare v_id uuid;v_version integer;v_branch uuid;begin perform public.eco_require_actor(p_actor_id,'targets.manage');select id into v_branch from public.eco_branches where active order by created_at limit 1;if p_payload->>'scope_type'='COMPANY' then select coalesce(max(version_number),0)+1 into v_version from public.eco_company_sales_targets where branch_id=v_branch and period_start=(p_payload->>'period_start')::date;insert into public.eco_company_sales_targets(branch_id,period_start,version_number,revenue_target,quantity_target,status,approved_by,approved_at) values(v_branch,(p_payload->>'period_start')::date,v_version,(p_payload->>'revenue_target')::numeric,nullif(p_payload->>'quantity_target','')::int,p_payload->>'status',case when p_payload->>'status'='APPROVED' then p_actor_id end,case when p_payload->>'status'='APPROVED' then now() end) returning id into v_id;elsif p_payload->>'scope_type'='EMPLOYEE' then select coalesce(max(version_number),0)+1 into v_version from public.eco_employee_sales_targets where employee_id=(p_payload->>'scope_id')::uuid and period_start=(p_payload->>'period_start')::date;insert into public.eco_employee_sales_targets(employee_id,period_start,version_number,revenue_target,quantity_target,status,approved_by,approved_at) values((p_payload->>'scope_id')::uuid,(p_payload->>'period_start')::date,v_version,(p_payload->>'revenue_target')::numeric,nullif(p_payload->>'quantity_target','')::int,p_payload->>'status',case when p_payload->>'status'='APPROVED' then p_actor_id end,case when p_payload->>'status'='APPROVED' then now() end) returning id into v_id;else raise exception 'ECO_TEAM_TARGET_REQUIRES_TEAM_ID';end if;return jsonb_build_object('target_id',v_id,'version',v_version);end $$;

create or replace function public.eco_save_commission_plan(p_actor_id uuid,p_payload jsonb) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$ declare v_plan uuid;v_version_id uuid;v_version integer;v_tier jsonb;begin perform public.eco_require_actor(p_actor_id,'commissions.manage');insert into public.eco_commission_plans(code,name,plan_scope) values(upper(regexp_replace(p_payload->>'plan_name','[^a-zA-Z0-9]+','_','g')),p_payload->>'plan_name',case when p_payload->>'sale_type'='MANAGER' then 'MANAGER' else 'INDIVIDUAL' end) on conflict(code) do update set name=excluded.name returning id into v_plan;select coalesce(max(version_number),0)+1 into v_version from public.eco_commission_plan_versions where commission_plan_id=v_plan;insert into public.eco_commission_plan_versions(commission_plan_id,version_number,effective_from,effective_to,status,eligible_sales_types,maturity_rule,fixed_maturity_days,minimum_fulfilled_percentage,month_end_minimum_hold_days,minimum_target_achievement_percentage,eligibility_target_scope,commission_base,approved_by,approved_at) values(v_plan,v_version,(p_payload->>'effective_from')::date,nullif(p_payload->>'effective_to','')::date,'APPROVED',array[p_payload->>'sale_type'],p_payload->>'maturity_rule',(p_payload->>'fixed_maturity_days')::int,(p_payload->>'minimum_fulfilled_percentage')::numeric,(p_payload->>'month_end_minimum_hold_days')::int,nullif(p_payload->>'manager_gate_percentage','')::numeric,case when p_payload->>'sale_type'='MANAGER' then 'COMPANY' end,case when p_payload->>'sale_type'='MANAGER' then 'ELIGIBLE_TEAM_SALES' end,p_actor_id,now()) returning id into v_version_id;for v_tier in select * from jsonb_array_elements(p_payload->'tiers') loop insert into public.eco_commission_tiers(plan_version_id,min_achievement_percentage,max_achievement_percentage,commission_rate_percentage,fixed_bonus) values(v_version_id,(v_tier->>'min_percentage')::numeric,nullif(v_tier->>'max_percentage','')::numeric,(v_tier->>'rate_percentage')::numeric,coalesce((v_tier->>'fixed_bonus')::numeric,0));end loop;return jsonb_build_object('plan_id',v_plan,'plan_version_id',v_version_id,'version',v_version);end $$;

create or replace function public.eco_save_menu_day(p_actor_id uuid,p_payload jsonb) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$ declare v_branch uuid;v_month uuid;v_id uuid;v_date date:=(p_payload->>'service_date')::date;begin perform public.eco_require_actor(p_actor_id,'menu.manage');select id into v_branch from public.eco_branches where active order by created_at limit 1;insert into public.eco_menu_months(branch_id,month_start) values(v_branch,date_trunc('month',v_date)::date) on conflict(branch_id,month_start) do update set status=public.eco_menu_months.status returning id into v_month;insert into public.eco_menu_days(menu_month_id,service_date,slot_code,meal_version_id,quantity,updated_by) values(v_month,v_date,p_payload->>'slot_code',(p_payload->>'meal_version_id')::uuid,(p_payload->>'quantity')::numeric,p_actor_id) on conflict(menu_month_id,service_date,slot_code) do update set meal_version_id=excluded.meal_version_id,quantity=excluded.quantity,updated_by=excluded.updated_by,updated_at=now() returning id into v_id;update public.eco_planning_exceptions set status='RESOLVED',resolved_at=now() where exception_type='MISSING_MENU' and service_date=v_date and status='OPEN';return jsonb_build_object('menu_day_id',v_id);end $$;

create or replace function public.eco_receive_inventory(p_actor_id uuid,p_payload jsonb) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$ declare v_receipt uuid;v_line jsonb;v_lot uuid;v_branch uuid;begin perform public.eco_require_actor(p_actor_id,'inventory.receive');select branch_id into strict v_branch from public.eco_purchase_orders where id=(p_payload->>'purchase_order_id')::uuid and status in('APPROVED','ORDERED','PARTIALLY_RECEIVED');insert into public.eco_goods_receipts(purchase_order_id,supplier_reference,received_by,idempotency_key) values((p_payload->>'purchase_order_id')::uuid,p_payload->>'supplier_reference',p_actor_id,p_payload->>'idempotency_key') returning id into v_receipt;for v_line in select * from jsonb_array_elements(p_payload->'lines') loop insert into public.eco_stock_lots(ingredient_id,goods_receipt_id,lot_number,expiry_date,received_quantity,unit_cost) values((v_line->>'ingredient_id')::uuid,v_receipt,v_line->>'lot_number',(v_line->>'expiry_date')::date,(v_line->>'quantity')::numeric,(v_line->>'unit_cost')::numeric) returning id into v_lot;insert into public.eco_stock_movements(branch_id,ingredient_id,lot_id,movement_type,quantity,unit_cost,source_type,source_id,idempotency_key,actor_id) values(v_branch,(v_line->>'ingredient_id')::uuid,v_lot,'RECEIPT',(v_line->>'quantity')::numeric,(v_line->>'unit_cost')::numeric,'goods_receipt',v_receipt,'receipt:'||v_receipt||':'||v_lot,p_actor_id);end loop;update public.eco_purchase_orders set status='RECEIVED' where id=(p_payload->>'purchase_order_id')::uuid;return jsonb_build_object('goods_receipt_id',v_receipt);end $$;

create or replace function public.eco_mark_notification_read(p_actor_id uuid,p_notification_id uuid) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$ begin perform public.eco_require_actor(p_actor_id,'notifications.read');update public.eco_notifications set status='READ',read_at=now() where id=p_notification_id and employee_id=p_actor_id;if not found then raise exception 'ECO_NOTIFICATION_FORBIDDEN' using errcode='42501';end if;return jsonb_build_object('notification_id',p_notification_id,'status','READ');end $$;

create or replace function public.eco_process_commission_maturity(p_run_key text) returns integer
language plpgsql security definer set search_path=public,pg_temp as $$
declare r record;v_days integer;v_fulfilled numeric;v_eligible boolean;v_achievement numeric;v_target numeric;v_tier public.eco_commission_tiers%rowtype;v_accrual uuid;v_count integer:=0;begin
 for r in select sc.*,cpv.maturity_rule,cpv.fixed_maturity_days,cpv.minimum_fulfilled_percentage,cpv.minimum_hold_days,cpv.month_end_minimum_hold_days,cpv.require_no_open_refund,cpv.require_no_open_cancellation,cpv.require_payment_reconciled,cpv.carry_pending_to_next_period from public.eco_sales_credit_events sc join public.eco_commission_plan_versions cpv on cpv.id=sc.plan_version_id where sc.lifecycle_state='PAYMENT_VERIFIED_PENDING_MATURITY' for update of sc skip locked loop
  v_days:=greatest(0,current_date-(select verified_at::date from public.eco_payments where invoice_id=r.invoice_id and status='VERIFIED' order by verified_at limit 1));
  select coalesce(100*sum(e.consumed_quantity)/nullif(sum(e.granted_quantity),0),case when o.order_type='A_LA_CARTE' and exists(select 1 from public.eco_fulfillments f where f.order_id=o.id and f.status='DELIVERED') then 100 else 0 end) into v_fulfilled from public.eco_orders o left join public.eco_subscriptions s on s.order_id=o.id left join public.eco_entitlements e on e.subscription_id=s.id where o.id=r.order_id group by o.id;
  v_eligible:=case r.maturity_rule when 'FIXED_DAYS_AFTER_PAYMENT' then v_days>=greatest(r.fixed_maturity_days,r.minimum_hold_days) when 'PERCENTAGE_OF_SUBSCRIPTION_FULFILLED' then v_fulfilled>=r.minimum_fulfilled_percentage when 'BOTH_CONDITIONS_REQUIRED' then v_days>=greatest(r.fixed_maturity_days,r.minimum_hold_days) and v_fulfilled>=r.minimum_fulfilled_percentage when 'EITHER_CONDITION_REQUIRED' then v_days>=greatest(r.fixed_maturity_days,r.minimum_hold_days) or v_fulfilled>=r.minimum_fulfilled_percentage when 'DELIVERY_COMPLETED' then v_fulfilled>=100 else false end;
  v_eligible:=v_eligible and(not r.require_no_open_refund or not exists(select 1 from public.eco_refunds rf where rf.invoice_id=r.invoice_id and rf.status not in('REJECTED','PAID'))) and(not r.require_no_open_cancellation or not exists(select 1 from public.eco_cancellations c where c.subscription_id=(select id from public.eco_subscriptions where order_id=r.order_id) and c.status not in('REJECTED','CLOSED'))) and(not r.require_payment_reconciled or exists(select 1 from public.eco_payments p where p.invoice_id=r.invoice_id and p.status='VERIFIED'));
  if extract(day from(select verified_at from public.eco_payments where invoice_id=r.invoice_id and status='VERIFIED' order by verified_at limit 1))>24 then v_eligible:=v_eligible and v_days>=r.month_end_minimum_hold_days;end if;
  if v_eligible then
   select revenue_target into v_target from public.eco_employee_sales_targets where employee_id=r.employee_id and period_start=r.period_start and status='APPROVED' order by version_number desc limit 1;select 100*(coalesce(sum(commissionable_value),0)+r.commissionable_value)/nullif(v_target,0) into v_achievement from public.eco_sales_credit_events where employee_id=r.employee_id and period_start=r.period_start and lifecycle_state in('ELIGIBLE_CONFIRMED','COMMISSION_ACCRUED','COMMISSION_PAYABLE','COMMISSION_PAID');select * into v_tier from public.eco_commission_tiers where plan_version_id=r.plan_version_id and approval_status='APPROVED' and min_achievement_percentage<=coalesce(v_achievement,0) and(max_achievement_percentage is null or max_achievement_percentage>coalesce(v_achievement,0)) order by min_achievement_percentage desc limit 1;
   update public.eco_sales_credit_events set lifecycle_state='ELIGIBLE_CONFIRMED',maturity_reason='استوفت شروط النضج: hold='||v_days||'d, fulfillment='||round(v_fulfilled,2)||'%' where id=r.id;
   if v_tier.id is not null then insert into public.eco_commission_accruals(sales_credit_event_id,employee_id,plan_version_id,tier_id,period_start,commissionable_value,rate_percentage,fixed_bonus,accrued_amount,status) values(r.id,r.employee_id,r.plan_version_id,v_tier.id,r.period_start,r.commissionable_value,v_tier.commission_rate_percentage,v_tier.fixed_bonus,round(r.commissionable_value*v_tier.commission_rate_percentage/100+v_tier.fixed_bonus,2),'ACCRUED') on conflict(sales_credit_event_id) do update set accrued_amount=excluded.accrued_amount returning id into v_accrual;insert into public.eco_commission_maturity_events(accrual_id,event_type,fulfilled_percentage,hold_days,eligibility_result,reasons) values(v_accrual,'MATURED',v_fulfilled,v_days,true,jsonb_build_array('POLICY_SATISFIED'));end if;v_count:=v_count+1;
  else update public.eco_sales_credit_events set maturity_reason='بانتظار شروط المدة/التنفيذ أو إغلاق Refund/Cancellation/Reconciliation',period_start=case when r.carry_pending_to_next_period and r.period_start<date_trunc('month',current_date)::date then date_trunc('month',current_date)::date else r.period_start end where id=r.id;end if;
 end loop;return v_count;
end $$;

create or replace function public.eco_run_background_job(p_job_name text,p_run_key text) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$ declare v_run uuid;v_count integer:=0;begin insert into public.eco_background_job_runs(job_name,run_key) values(p_job_name,p_run_key) on conflict(run_key) do update set run_key=excluded.run_key returning id into v_run;if p_job_name='auto-resume' then update public.eco_subscriptions s set status='ACTIVE' where status='PAUSED' and exists(select 1 from public.eco_subscription_pauses p where p.subscription_id=s.id and p.status='ACTIVE' and p.ends_on<current_date);get diagnostics v_count=row_count;update public.eco_subscription_pauses set status='AUTO_RESUMED',auto_resumed_at=now() where status='ACTIVE' and ends_on<current_date;elsif p_job_name='renewals' then insert into public.eco_renewal_opportunities(subscription_id,cycle_id,customer_id,assigned_employee_id,due_date,remaining_balance,risk_score,top_reasons,recommended_action) select s.id,s.current_cycle_id,s.customer_id,s.sales_owner_id,s.renewal_due_date,coalesce(sum(e.granted_quantity-e.consumed_quantity),0),case when t.id is not null then 70 else 25 end,jsonb_build_array(case when t.id is not null then 'OPEN_COMPLAINT' else 'RENEWAL_DUE' end),'تواصل مع العميل وحدد التجديد' from public.eco_subscriptions s join public.eco_entitlements e on e.subscription_id=s.id left join public.eco_tickets t on t.customer_id=s.customer_id and t.status='OPEN' where s.status='ACTIVE' and(s.renewal_due_date<=current_date+7 or e.granted_quantity-e.consumed_quantity<=3) group by s.id,t.id on conflict(cycle_id) do nothing;get diagnostics v_count=row_count;elsif p_job_name='notifications' then insert into public.eco_notifications(employee_id,title,body,priority,entity_type,entity_id,deep_link,due_at) select ro.assigned_employee_id,'تجديد قريب','متبقي '||ro.remaining_balance||' استحقاق','HIGH','renewal_opportunity',ro.id,'/clients',ro.due_date::timestamptz from public.eco_renewal_opportunities ro where ro.status='OPEN' on conflict do nothing;get diagnostics v_count=row_count;elsif p_job_name='outbox' then update public.eco_outbox_events set status='PROCESSED',processed_at=now() where status='PENDING' and available_at<=now();get diagnostics v_count=row_count;elsif p_job_name='commission-maturity' then v_count:=public.eco_process_commission_maturity(p_run_key);elsif p_job_name='kpi-snapshots' then v_count:=0;else raise exception 'ECO_UNKNOWN_JOB:%',p_job_name;end if;update public.eco_background_job_runs set status='COMPLETED',processed_count=v_count,completed_at=now() where id=v_run;return jsonb_build_object('job',p_job_name,'processed',v_count,'run_id',v_run);exception when others then update public.eco_background_job_runs set status='FAILED',error=sqlerrm,completed_at=now() where id=v_run;raise;end $$;

create or replace function public.eco_close_financial_period(p_actor_id uuid,p_period_id uuid) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$ declare v_blockers integer;begin perform public.eco_require_actor(p_actor_id,'accounting.close');select count(*) into v_blockers from public.eco_accounting_close_blockers_v where period_id=p_period_id;if v_blockers>0 then raise exception 'ECO_CLOSE_BLOCKED:%',v_blockers using errcode='23514';end if;update public.eco_financial_periods set status='CLOSED',closed_by=p_actor_id,closed_at=now() where id=p_period_id and status<>'CLOSED';return jsonb_build_object('period_id',p_period_id,'status','CLOSED');end $$;

create or replace function public.eco_purge_demo_data(p_actor_id uuid,p_idempotency_key text) returns jsonb
language plpgsql security definer set search_path=public,pg_temp as $$
declare v_count integer;v_customer_ids uuid[];v_employee_ids uuid[];begin
 perform public.eco_require_actor(p_actor_id,'system.demo.manage');
 select coalesce(array_agg(id),'{}'::uuid[]) into v_customer_ids from public.eco_customers where is_demo;
 select coalesce(array_agg(id),'{}'::uuid[]) into v_employee_ids from public.eco_employees where is_demo;
 delete from public.eco_notifications where employee_id=any(v_employee_ids) or entity_id=any(v_customer_ids);
 delete from public.eco_customer_timeline where customer_id=any(v_customer_ids);
 delete from public.eco_customer_assignments where customer_id=any(v_customer_ids);
 delete from public.eco_customer_addresses where customer_id=any(v_customer_ids);
 delete from public.eco_payment_proofs where payment_id in(select p.id from public.eco_payments p join public.eco_invoices i on i.id=p.invoice_id where i.customer_id=any(v_customer_ids));
 delete from public.eco_payment_allocations where invoice_id in(select id from public.eco_invoices where customer_id=any(v_customer_ids));
 delete from public.eco_payments where invoice_id in(select id from public.eco_invoices where customer_id=any(v_customer_ids));
 delete from public.eco_invoice_lines where invoice_id in(select id from public.eco_invoices where customer_id=any(v_customer_ids));
 delete from public.eco_invoices where customer_id=any(v_customer_ids);
 delete from public.eco_orders where customer_id=any(v_customer_ids);
 delete from public.eco_customers where id=any(v_customer_ids);get diagnostics v_count=row_count;
 delete from public.eco_employee_role_assignments where employee_id=any(v_employee_ids);
 delete from public.eco_employees where id=any(v_employee_ids);
 return jsonb_build_object('deleted_demo_customers',v_count,'idempotency_key',p_idempotency_key);
end $$;

create or replace view public.eco_ceo_dashboard_v with(security_invoker=false) as
select b.id,
 (select count(*) from public.eco_subscriptions s join public.eco_orders o on o.id=s.order_id where o.branch_id=b.id and s.status='ACTIVE') active_members,
 (select coalesce(sum(rs.recognized_amount),0) from public.eco_revenue_schedules rs join public.eco_invoice_lines il on il.id=rs.invoice_line_id join public.eco_invoices i on i.id=il.invoice_id where i.branch_id=b.id) recognized_revenue,
 (select coalesce(sum((i.total-i.delivery_fees)/greatest(pv.service_days,1)*30),0) from public.eco_subscriptions s join public.eco_orders o on o.id=s.order_id join public.eco_invoices i on i.order_id=o.id join public.eco_package_versions pv on pv.id=s.package_version_id where o.branch_id=b.id and s.status='ACTIVE') mrr,
 (select coalesce(sum(commissionable_value),0) from public.eco_sales_credit_events e join public.eco_orders o on o.id=e.order_id where o.branch_id=b.id and e.lifecycle_state='ELIGIBLE_CONFIRMED') confirmed_sales,
 (select 100.0*count(*) filter(where renewed_cycle_id is not null)/nullif(count(*),0) from public.eco_renewal_opportunities ro join public.eco_subscriptions s on s.id=ro.subscription_id join public.eco_orders o on o.id=s.order_id where o.branch_id=b.id) renewal_rate,
 (select 100.0*count(*) filter(where s.status='CANCELED')/nullif(count(*),0) from public.eco_subscriptions s join public.eco_orders o on o.id=s.order_id where o.branch_id=b.id and s.activated_at<date_trunc('month',current_date)) logo_churn,
 (select 100.0*(coalesce(sum(rs.recognized_amount),0)-coalesce((select sum(abs(sm.quantity)*sm.unit_cost) from public.eco_stock_movements sm where sm.branch_id=b.id and sm.movement_type in('PRODUCTION_CONSUMPTION','WASTE')),0))/nullif(coalesce(sum(rs.recognized_amount),0),0) from public.eco_revenue_schedules rs join public.eco_invoice_lines il on il.id=rs.invoice_line_id join public.eco_invoices i on i.id=il.invoice_id where i.branch_id=b.id) contribution_margin,
 (select 100.0*count(*) filter(where delivered_at<=promised_end)/nullif(count(*) filter(where state='DELIVERED'),0) from public.eco_route_stops st join public.eco_routes r on r.id=st.route_id where r.branch_id=b.id) delivery_sla,
 now() freshness from public.eco_branches b where b.active;

create or replace view public.eco_operations_dashboard_v with(security_invoker=false) as select b.id,(select coalesce(sum(required_quantity),0) from public.eco_production_demand d where d.branch_id=b.id and d.service_date=current_date+1) production_demand,(select least(100,100.0*coalesce(sum(required_quantity),0)/nullif(500,0)) from public.eco_production_demand d where d.branch_id=b.id and d.service_date=current_date+1) kitchen_utilization,(select 100.0*count(*) filter(where st.delivered_at<=st.promised_end)/nullif(count(*) filter(where st.state='DELIVERED'),0) from public.eco_route_stops st join public.eco_routes r on r.id=st.route_id where r.branch_id=b.id and r.route_date=current_date) delivery_sla,(select count(*) from public.eco_planning_exceptions where status='OPEN') open_exceptions,now() freshness from public.eco_branches b where b.active;
create or replace view public.eco_finance_dashboard_v with(security_invoker=false) as select b.id,(select coalesce(sum(p.verified_amount),0) from public.eco_payments p join public.eco_invoices i on i.id=p.invoice_id where i.branch_id=b.id and p.status='VERIFIED') verified_collections,(select coalesce(sum(deferred_amount),0) from public.eco_revenue_schedules rs join public.eco_invoice_lines il on il.id=rs.invoice_line_id join public.eco_invoices i on i.id=il.invoice_id where i.branch_id=b.id) deferred_revenue,(select count(*) from public.eco_payments p join public.eco_invoices i on i.id=p.invoice_id where i.branch_id=b.id and p.status='VERIFIED' and not exists(select 1 from public.eco_payment_allocations pa where pa.payment_id=p.id)) unallocated_payments,(select count(*) from public.eco_reconciliations where branch_id=b.id and status<>'CLOSED') open_blockers,now() freshness from public.eco_branches b where b.active;

create or replace view public.eco_sales_agent_dashboard_v with(security_invoker=false) as
with periods as(select e.id employee_id,date_trunc('month',current_date)::date period_start from public.eco_employees e where e.status='ACTIVE'),t as(select distinct on(employee_id,period_start) employee_id,period_start,revenue_target from public.eco_employee_sales_targets where status='APPROVED' order by employee_id,period_start,version_number desc),s as(select employee_id,period_start,sum(booked_value) booked_paid,sum(booked_value) filter(where lifecycle_state='PAYMENT_VERIFIED_PENDING_MATURITY') pending_maturity,sum(commissionable_value) filter(where lifecycle_state in('ELIGIBLE_CONFIRMED','COMMISSION_ACCRUED','COMMISSION_PAYABLE','COMMISSION_PAID')) confirmed_eligible,max(maturity_reason) maturity_reason from public.eco_sales_credit_events group by employee_id,period_start),c as(select employee_id,period_start,sum(accrued_amount) estimated_commission,sum(accrued_amount) filter(where status in('PAYABLE','PAID')) payable_commission from public.eco_commission_accruals group by employee_id,period_start)
select p.employee_id id,p.employee_id scope_employee_id,p.period_start,coalesce(t.revenue_target,0) target,coalesce(s.booked_paid,0) booked_paid,coalesce(s.pending_maturity,0) pending_maturity,coalesce(s.confirmed_eligible,0) confirmed_eligible,100*coalesce(s.booked_paid,0)/nullif(t.revenue_target,0) achievement_booked,100*coalesce(s.confirmed_eligible,0)/nullif(t.revenue_target,0) achievement_confirmed,coalesce(c.estimated_commission,0) estimated_commission,coalesce(c.payable_commission,0) payable_commission,coalesce((select commission_rate_percentage||'%' from public.eco_commission_tiers ct where ct.min_achievement_percentage<=100*coalesce(s.confirmed_eligible,0)/nullif(t.revenue_target,0) and(ct.max_achievement_percentage is null or ct.max_achievement_percentage>100*coalesce(s.confirmed_eligible,0)/nullif(t.revenue_target,0)) order by ct.min_achievement_percentage desc limit 1),'—') current_tier,s.maturity_reason from periods p left join t on t.employee_id=p.employee_id and t.period_start=p.period_start left join s on s.employee_id=p.employee_id and s.period_start=p.period_start left join c on c.employee_id=p.employee_id and c.period_start=p.period_start;

create or replace view public.eco_sales_manager_dashboard_v with(security_invoker=false) as select tm.team_id,tm.employee_id id,e.full_name employee_name,date_trunc('month',current_date)::date period_start,coalesce(t.revenue_target,0) target,coalesce(sum(sc.booked_value),0) booked_paid,coalesce(sum(sc.booked_value) filter(where sc.lifecycle_state='PAYMENT_VERIFIED_PENDING_MATURITY'),0) pending_maturity,coalesce(sum(sc.commissionable_value) filter(where sc.lifecycle_state in('ELIGIBLE_CONFIRMED','COMMISSION_ACCRUED','COMMISSION_PAYABLE','COMMISSION_PAID')),0) confirmed_eligible,100*coalesce(sum(sc.commissionable_value) filter(where sc.lifecycle_state in('ELIGIBLE_CONFIRMED','COMMISSION_ACCRUED','COMMISSION_PAYABLE','COMMISSION_PAID')),0)/nullif(t.revenue_target,0) achievement_confirmed from public.eco_team_members tm join public.eco_employees e on e.id=tm.employee_id left join public.eco_employee_sales_targets t on t.employee_id=e.id and t.period_start=date_trunc('month',current_date)::date and t.status='APPROVED' left join public.eco_sales_credit_events sc on sc.employee_id=e.id and sc.period_start=date_trunc('month',current_date)::date group by tm.team_id,tm.employee_id,e.full_name,t.revenue_target;

create or replace view public.eco_crm_leads_v with(security_invoker=false) as select l.id,l.assigned_employee_id scope_employee_id,l.lead_number,l.full_name,regexp_replace(l.phone,'(.{3}).*(.{3})','\1••••\2') phone_masked,l.stage,ls.name_ar source_name,e.full_name assigned_agent,extract(epoch from(l.first_response_at-l.created_at))/60 first_response_minutes,l.next_action_at,l.created_at,concat_ws(' ',l.lead_number,l.full_name,l.phone) search_text from public.eco_leads l join public.eco_lead_sources ls on ls.code=l.source_code join public.eco_employees e on e.id=l.assigned_employee_id;
create or replace view public.eco_subscribers_directory_v with(security_invoker=false) as select s.id subscription_id,s.id,s.subscription_number,c.customer_number,c.full_name,regexp_replace(c.phone_display,'(.{3}).*(.{3})','\1••••\2') phone_masked,s.sales_owner_id scope_employee_id,e.full_name sales_owner_name,s.status subscription_status,p.name_ar plan_name,sum(en.granted_quantity-en.consumed_quantity-en.reserved_quantity) remaining_entitlements,s.expected_end_date,s.renewal_due_date,z.name_ar zone_name,max(sp.ends_on) filter(where sp.status='ACTIVE') pause_until,coalesce(max(rs.score) filter(where rs.score_type='CHURN_RISK'),0)*100 churn_risk_score,concat_ws(' ',c.customer_number,c.full_name,c.phone_display,s.subscription_number) search_text from public.eco_subscriptions s join public.eco_customers c on c.id=s.customer_id join public.eco_employees e on e.id=s.sales_owner_id join public.eco_orders o on o.id=s.order_id join public.eco_customer_addresses a on a.id=o.address_id join public.eco_zones z on z.id=a.zone_id join public.eco_package_versions pv on pv.id=s.package_version_id join public.eco_packages p on p.id=pv.package_id left join public.eco_entitlements en on en.subscription_id=s.id left join public.eco_subscription_pauses sp on sp.subscription_id=s.id left join public.eco_rule_scores rs on rs.subject_id=s.id group by s.id,c.id,e.full_name,p.name_ar,z.name_ar;
create or replace view public.eco_customer_360_v with(security_invoker=false) as select c.id,c.id customer_id,ca.employee_id scope_employee_id,c.customer_number,c.full_name,regexp_replace(c.phone_display,'(.{3}).*(.{3})','\1••••\2') phone_masked,c.status,(select coalesce(sum(pa.amount),0) from public.eco_payment_allocations pa join public.eco_invoices i on i.id=pa.invoice_id where i.customer_id=c.id) total_paid,(select count(*) from public.eco_orders where customer_id=c.id) total_orders,(select count(*) from public.eco_tickets where customer_id=c.id) complaints_count,c.created_at,concat_ws(' ',c.customer_number,c.full_name,c.phone_display) search_text from public.eco_customers c left join public.eco_customer_assignments ca on ca.customer_id=c.id and ca.assignment_type='SALES_OWNER' and ca.effective_from<=current_date and(ca.effective_to is null or ca.effective_to>=current_date);
create or replace view public.eco_orders_v with(security_invoker=false) as select o.id,o.sales_owner_id scope_employee_id,o.order_number,i.id invoice_id,i.invoice_number,c.full_name customer_name,o.order_type,i.total invoice_total,p.method payment_method,p.status payment_status,o.status order_status,o.created_at,concat_ws(' ',o.order_number,i.invoice_number,c.full_name) search_text from public.eco_orders o join public.eco_customers c on c.id=o.customer_id join public.eco_invoices i on i.order_id=o.id left join lateral(select * from public.eco_payments p where p.invoice_id=i.id order by p.created_at desc limit 1)p on true;

create or replace view public.eco_accounting_verification_queue_v with(security_invoker=false) as select p.id payment_id,p.id,i.id invoice_id,i.invoice_number,c.full_name customer_name,p.method,i.total expected_amount,p.declared_amount,p.reference,coalesce((select max(status) from public.eco_payment_proofs pp where pp.invoice_id=i.id),'MISSING') proof_status,exists(select 1 from public.eco_payments p2 where p2.id<>p.id and p2.method=p.method and p2.reference=p.reference and p2.status='VERIFIED') duplicate_reference,p.created_at from public.eco_payments p join public.eco_invoices i on i.id=p.invoice_id join public.eco_customers c on c.id=p.customer_id where p.status in('PENDING_PAYMENT','PENDING_VERIFICATION');
create or replace view public.eco_accounting_close_blockers_v with(security_invoker=false) as select p.id,pd.id period_id,'UNALLOCATED_PAYMENT' blocker_type,p.id::text reference,p.verified_amount amount,'HIGH' severity,e.full_name owner_name,p.verified_at opened_at from public.eco_payments p join public.eco_invoices i on i.id=p.invoice_id join public.eco_financial_periods pd on pd.branch_id=i.branch_id and p.verified_at::date between pd.period_start and pd.period_end left join public.eco_employees e on e.id=p.verified_by where p.status='VERIFIED' and not exists(select 1 from public.eco_payment_allocations pa where pa.payment_id=p.id)
union all select ch.id,pd.id,'CASH_VARIANCE',ch.id::text,ch.difference_amount,'HIGH',e.full_name,ch.created_at from public.eco_cash_handovers ch join public.eco_routes r on r.id=ch.route_id join public.eco_financial_periods pd on pd.branch_id=r.branch_id and r.route_date between pd.period_start and pd.period_end left join public.eco_employees e on e.id=ch.accounting_employee_id where ch.state='VARIANCE_OPEN';

create or replace view public.eco_kitchen_daily_demand_v with(security_invoker=false) as select d.id,d.service_date,ms.name_ar slot_name,m.name_ar meal_name,mv.version_number meal_version,d.size_code,d.required_quantity,coalesce(sum(bi.planned_quantity),0) batched_quantity,greatest(d.required_quantity-coalesce(sum(bi.planned_quantity),0),0) shortage_quantity,case when d.locked_at is null then 'OPEN' else 'LOCKED' end cutoff_status,(array_agg(bi.batch_id) filter(where bi.batch_id is not null))[1] batch_id from public.eco_production_demand d join public.eco_meal_versions mv on mv.id=d.meal_version_id join public.eco_meals m on m.id=mv.meal_id join public.eco_meal_slots ms on ms.code=d.slot_code left join public.eco_production_batch_items bi on bi.demand_id=d.id group by d.id,ms.name_ar,m.name_ar,mv.version_number;
create or replace view public.eco_kitchen_batches_v with(security_invoker=false) as select b.id,b.batch_number,b.service_date,b.status,sum(bi.planned_quantity) planned_quantity,sum(bi.actual_yield) actual_yield,sum(bi.waste_quantity) waste_quantity,sum(bi.shortage_quantity) shortage_quantity,b.qa_released_at from public.eco_production_batches b join public.eco_production_batch_items bi on bi.batch_id=b.id group by b.id;
create or replace view public.eco_inventory_stock_v with(security_invoker=false) as select i.id,i.code ingredient_code,i.name_ar ingredient_name,coalesce(sum(sm.quantity),0) on_hand,i.base_unit unit_code,coalesce(sum(sm.quantity) filter(where sl.expiry_date<=current_date+7),0) expiring_quantity,0::numeric reserved_quantity,coalesce(sum(sm.quantity),0) available_quantity,case when coalesce(sum(sm.quantity),0)<i.min_stock then 'SHORTAGE' else 'OK' end shortage_status,concat_ws(' ',i.code,i.name_ar) search_text from public.eco_ingredients i left join public.eco_stock_movements sm on sm.ingredient_id=i.id left join public.eco_stock_lots sl on sl.id=sm.lot_id group by i.id;
create or replace view public.eco_dispatcher_routes_v with(security_invoker=false) as select r.id,r.route_date,r.route_number,z.name_ar zone_name,w.name_ar window_name,e.full_name rider_name,count(st.id) stop_count,count(st.id) filter(where st.state='DELIVERED') delivered_count,count(st.id) filter(where st.state='FAILED') failed_count,coalesce(sum(st.cod_amount),0) cod_exposure,r.status route_status from public.eco_routes r join public.eco_zones z on z.id=r.zone_id join public.eco_delivery_windows w on w.id=r.delivery_window_id left join public.eco_riders rd on rd.id=r.rider_id left join public.eco_employees e on e.id=rd.employee_id left join public.eco_route_stops st on st.route_id=r.id group by r.id,z.name_ar,w.name_ar,e.full_name;
create or replace view public.eco_rider_today_route_v with(security_invoker=false) as select st.id,rd.employee_id rider_employee_id,r.id route_id,st.sequence_no,c.full_name customer_name,a.address_line,(select count(*) from public.eco_stop_pack_units where route_stop_id=st.id) pack_count,st.cod_amount,st.state,coalesce(a.map_url,'https://maps.google.com/?q='||a.latitude||','||a.longitude) navigation_url from public.eco_route_stops st join public.eco_routes r on r.id=st.route_id join public.eco_riders rd on rd.id=r.rider_id join public.eco_customers c on c.id=st.customer_id join public.eco_customer_addresses a on a.id=st.address_id where r.route_date=current_date;

create or replace view public.eco_commissions_v with(security_invoker=false) as select ca.id,ca.employee_id scope_employee_id,ca.period_start,e.full_name employee_name,cp.name plan_name,sum(ca.commissionable_value) booked_value,sum(ca.commissionable_value) filter(where ca.status='PENDING_MATURITY') pending_value,sum(ca.commissionable_value) filter(where ca.status in('ELIGIBLE','PAYABLE','PAID')) eligible_value,sum(ca.accrued_amount) accrued_amount,sum(ca.accrued_amount) filter(where ca.status='PAYABLE') payable_amount,sum(ca.accrued_amount) filter(where ca.status='PAID') paid_amount,coalesce(sum(cr.amount),0) clawback_amount from public.eco_commission_accruals ca join public.eco_employees e on e.id=ca.employee_id join public.eco_commission_plan_versions cpv on cpv.id=ca.plan_version_id join public.eco_commission_plans cp on cp.id=cpv.commission_plan_id left join public.eco_commission_reversals cr on cr.accrual_id=ca.id group by ca.id,e.full_name,cp.name;
create or replace view public.eco_targets_v with(security_invoker=false) as select t.id,t.period_start,'EMPLOYEE' scope_type,e.full_name scope_name,t.revenue_target,coalesce(sum(sc.booked_value),0) booked_actual,coalesce(sum(sc.commissionable_value) filter(where sc.lifecycle_state in('ELIGIBLE_CONFIRMED','COMMISSION_ACCRUED','COMMISSION_PAYABLE','COMMISSION_PAID')),0) confirmed_actual,coalesce(sum(sc.booked_value),0)/greatest(extract(day from current_date),1)*extract(day from(date_trunc('month',current_date)+interval '1 month - 1 day')) forecast,coalesce(sum(sc.booked_value),0)-t.revenue_target variance,case when coalesce(sum(sc.booked_value),0)>=t.revenue_target then 'GREEN' when coalesce(sum(sc.booked_value),0)>=t.revenue_target*.8 then 'AMBER' else 'RED' end rag_status from public.eco_employee_sales_targets t join public.eco_employees e on e.id=t.employee_id left join public.eco_sales_credit_events sc on sc.employee_id=t.employee_id and sc.period_start=t.period_start where t.status='APPROVED' group by t.id,e.full_name;
create or replace view public.eco_catalog_v with(security_invoker=false) as select pv.id,p.code package_code,p.name_ar package_name,pv.version_number,pv.size_code,pv.service_days,string_agg(ps.slot_code||'×'||ps.quantity,', ' order by ms.sort_order) meal_slots,pv.frequency_policy,pbi.unit_price price,pv.effective_from,pv.status,concat_ws(' ',p.code,p.name_ar,pv.size_code) search_text from public.eco_package_versions pv join public.eco_packages p on p.id=pv.package_id join public.eco_package_slots ps on ps.package_version_id=pv.id join public.eco_meal_slots ms on ms.code=ps.slot_code left join public.eco_price_book_items pbi on pbi.package_version_id=pv.id group by pv.id,p.id,pbi.unit_price;
create or replace view public.eco_menu_planner_v with(security_invoker=false) as select md.id,md.service_date,to_char(md.service_date,'TMDay') day_name,ms.name_ar slot_name,m.name_ar meal_name,mv.version_number meal_version,md.quantity,case when pe.id is null then 'OK' else 'OPEN' end planning_exception,mm.locked_at from public.eco_menu_days md join public.eco_menu_months mm on mm.id=md.menu_month_id join public.eco_meal_slots ms on ms.code=md.slot_code join public.eco_meal_versions mv on mv.id=md.meal_version_id join public.eco_meals m on m.id=mv.meal_id left join public.eco_planning_exceptions pe on pe.service_date=md.service_date and pe.exception_type='MISSING_MENU' and pe.status='OPEN';
create or replace view public.eco_notifications_v with(security_invoker=false) as select n.id,n.employee_id scope_employee_id,n.title,n.body,n.priority,n.due_at,n.status,n.created_at from public.eco_notifications n;
create or replace view public.eco_investor_certified_metrics_v with(security_invoker=false) as select ks.id,ks.period_start,md.name_ar metric_name,ks.value metric_value,ks.numerator,ks.denominator,ks.definition_version,ks.certification_status,ks.calculated_at snapshot_at,max(ks.value) filter(where md.metric_code='MRR') over(partition by ks.period_start) mrr,max(ks.value) filter(where md.metric_code='ARR') over(partition by ks.period_start) arr,max(ks.value) filter(where md.metric_code='REVENUE_GROWTH') over(partition by ks.period_start) revenue_growth,max(ks.value) filter(where md.metric_code='CONTRIBUTION_MARGIN') over(partition by ks.period_start) contribution_margin,max(ks.value) filter(where md.metric_code='LOGO_RETENTION') over(partition by ks.period_start) logo_retention,max(ks.value) filter(where md.metric_code='RENEWAL_RATE') over(partition by ks.period_start) renewal_rate,max(ks.value) filter(where md.metric_code='LTV_CAC') over(partition by ks.period_start) ltv_cac,max(ks.value) filter(where md.metric_code='DELIVERY_SLA') over(partition by ks.period_start) delivery_sla from public.eco_kpi_snapshots ks join public.eco_metric_definitions md on md.id=ks.metric_definition_id where ks.certification_status='CERTIFIED';
create or replace view public.eco_audit_v with(security_invoker=false) as select a.id,a.occurred_at,e.full_name actor_name,a.action,a.entity_type,a.entity_id,a.request_id,a.reason,a.source from public.eco_audit_events a left join public.eco_employees e on e.id=a.actor_id;

create or replace view public.eco_zone_options_v as select id value,name_ar label from public.eco_zones where active;
create or replace view public.eco_employee_options_v as select id value,full_name||' — '||employee_number label from public.eco_employees where status='ACTIVE';
create or replace view public.eco_customer_options_v as select c.id value,c.full_name||' — '||c.customer_number label,ca.employee_id scope_employee_id from public.eco_customers c left join public.eco_customer_assignments ca on ca.customer_id=c.id and ca.assignment_type='SALES_OWNER' and ca.effective_from<=current_date and(ca.effective_to is null or ca.effective_to>=current_date) where c.status='ACTIVE';
create or replace view public.eco_package_options_v as select pv.id value,p.name_ar||' — '||pv.size_code||' — '||coalesce(pbi.unit_price,0)||' ج' label from public.eco_package_versions pv join public.eco_packages p on p.id=pv.package_id left join public.eco_price_book_items pbi on pbi.package_version_id=pv.id where pv.status='APPROVED';
create or replace view public.eco_address_options_v as select a.id value,c.full_name||' — '||a.label||' — '||a.address_line label,ca.employee_id scope_employee_id from public.eco_customer_addresses a join public.eco_customers c on c.id=a.customer_id left join public.eco_customer_assignments ca on ca.customer_id=c.id and ca.assignment_type='SALES_OWNER' and ca.effective_from<=current_date and(ca.effective_to is null or ca.effective_to>=current_date) where a.active;
create or replace view public.eco_delivery_window_options_v as select id value,name_ar||' ('||start_time||' - '||end_time||')' label from public.eco_delivery_windows where active;
create or replace view public.eco_bank_account_options_v as select id value,name||' — '||coalesce(masked_account,'') label from public.eco_bank_accounts where active;
create or replace view public.eco_meal_options_v as select mv.id value,m.name_ar||' — v'||mv.version_number label from public.eco_meal_versions mv join public.eco_meals m on m.id=mv.meal_id where mv.status='APPROVED';
create or replace view public.eco_po_options_v as select po.id value,po.po_number||' — '||s.name label from public.eco_purchase_orders po join public.eco_suppliers s on s.id=po.supplier_id where po.status in('APPROVED','ORDERED','PARTIALLY_RECEIVED');

create or replace function public.eco_complete_payment_proof(p_actor_id uuid,p_storage_path text) returns jsonb language plpgsql security definer set search_path=public,storage,pg_temp as $$ begin perform public.eco_require_actor(p_actor_id,'payment_proofs.upload');if not exists(select 1 from storage.objects where bucket_id='payment-proofs' and name=p_storage_path) then raise exception 'ECO_PROOF_OBJECT_NOT_FOUND';end if;update public.eco_payment_proofs set status='UPLOADED' where storage_path=p_storage_path and uploaded_by=p_actor_id;if not found then raise exception 'ECO_PROOF_METADATA_NOT_FOUND';end if;return jsonb_build_object('storage_path',p_storage_path,'status','UPLOADED');end $$;

create index if not exists eco_customers_phone_idx on public.eco_customers(normalized_phone);
create index if not exists eco_leads_owner_stage_idx on public.eco_leads(assigned_employee_id,stage,created_at desc);
create index if not exists eco_orders_owner_created_idx on public.eco_orders(sales_owner_id,created_at desc);
create index if not exists eco_payments_queue_idx on public.eco_payments(status,created_at) where status in('PENDING_PAYMENT','PENDING_VERIFICATION');
create index if not exists eco_fulfillments_service_idx on public.eco_fulfillments(service_date,status,meal_version_id,size_code);
create index if not exists eco_entitlement_ledger_source_idx on public.eco_entitlement_ledger(source_type,source_id);
create index if not exists eco_routes_date_idx on public.eco_routes(route_date,status,zone_id);
create index if not exists eco_route_stops_state_idx on public.eco_route_stops(route_id,state,sequence_no);
create index if not exists eco_stock_movements_item_idx on public.eco_stock_movements(ingredient_id,occurred_at desc);
create index if not exists eco_credit_events_period_idx on public.eco_sales_credit_events(employee_id,period_start,lifecycle_state);
create index if not exists eco_outbox_pending_idx on public.eco_outbox_events(available_at) where status='PENDING';
create index if not exists eco_notifications_employee_idx on public.eco_notifications(employee_id,status,created_at desc);
create index if not exists eco_audit_entity_idx on public.eco_audit_events(entity_type,entity_id,occurred_at desc);

do $rls$ declare t text;begin
 for t in select tablename from pg_tables where schemaname='public' and tablename like 'eco\_%' escape '\' and tablename<>'eco_schema_migrations' loop execute format('alter table public.%I enable row level security',t);execute format('revoke all on table public.%I from anon,authenticated',t);end loop;
end $rls$;

drop policy if exists eco_employees_self on public.eco_employees;create policy eco_employees_self on public.eco_employees for select to authenticated using(auth_user_id=auth.uid());
drop policy if exists eco_customers_scoped on public.eco_customers;create policy eco_customers_scoped on public.eco_customers for select to authenticated using(public.eco_has_permission('customers.read') and public.eco_customer_in_scope(id));
drop policy if exists eco_addresses_scoped on public.eco_customer_addresses;create policy eco_addresses_scoped on public.eco_customer_addresses for select to authenticated using(public.eco_customer_in_scope(customer_id));
drop policy if exists eco_assignments_scoped on public.eco_customer_assignments;create policy eco_assignments_scoped on public.eco_customer_assignments for select to authenticated using(public.eco_customer_in_scope(customer_id));
drop policy if exists eco_leads_scoped on public.eco_leads;create policy eco_leads_scoped on public.eco_leads for select to authenticated using(assigned_employee_id=public.eco_current_employee_id() or exists(select 1 from public.eco_team_members mine join public.eco_team_members theirs on theirs.team_id=mine.team_id where mine.employee_id=public.eco_current_employee_id() and theirs.employee_id=assigned_employee_id));
drop policy if exists eco_orders_scoped on public.eco_orders;create policy eco_orders_scoped on public.eco_orders for select to authenticated using(public.eco_has_permission('orders.read') and public.eco_customer_in_scope(customer_id));
drop policy if exists eco_subscriptions_scoped on public.eco_subscriptions;create policy eco_subscriptions_scoped on public.eco_subscriptions for select to authenticated using(public.eco_has_permission('subscriptions.read') and public.eco_customer_in_scope(customer_id));
drop policy if exists eco_invoices_scoped on public.eco_invoices;create policy eco_invoices_scoped on public.eco_invoices for select to authenticated using(public.eco_has_permission('orders.read') and public.eco_customer_in_scope(customer_id));
drop policy if exists eco_payments_finance on public.eco_payments;create policy eco_payments_finance on public.eco_payments for select to authenticated using(public.eco_has_permission('payments.verify'));
drop policy if exists eco_production_demand_kitchen on public.eco_production_demand;create policy eco_production_demand_kitchen on public.eco_production_demand for select to authenticated using(public.eco_has_permission('kitchen.demand.read'));
drop policy if exists eco_batches_kitchen on public.eco_production_batches;create policy eco_batches_kitchen on public.eco_production_batches for select to authenticated using(public.eco_has_permission('kitchen.batch.read'));
drop policy if exists eco_routes_dispatch on public.eco_routes;create policy eco_routes_dispatch on public.eco_routes for select to authenticated using(public.eco_has_permission('routes.manage') or exists(select 1 from public.eco_riders rd where rd.id=rider_id and rd.employee_id=public.eco_current_employee_id()));
drop policy if exists eco_stops_rider on public.eco_route_stops;create policy eco_stops_rider on public.eco_route_stops for select to authenticated using(public.eco_has_permission('routes.manage') or exists(select 1 from public.eco_routes r join public.eco_riders rd on rd.id=r.rider_id where r.id=route_id and rd.employee_id=public.eco_current_employee_id()));
drop policy if exists eco_notifications_own on public.eco_notifications;create policy eco_notifications_own on public.eco_notifications for select to authenticated using(employee_id=public.eco_current_employee_id());
drop policy if exists eco_kpi_investor on public.eco_kpi_snapshots;create policy eco_kpi_investor on public.eco_kpi_snapshots for select to authenticated using(certification_status='CERTIFIED' and public.eco_has_permission('investor.metrics.read'));

grant select on public.eco_employees,public.eco_customers,public.eco_customer_addresses,public.eco_customer_assignments,public.eco_leads,public.eco_orders,public.eco_invoices,public.eco_subscriptions,public.eco_payments,public.eco_production_demand,public.eco_production_batches,public.eco_routes,public.eco_route_stops,public.eco_notifications,public.eco_kpi_snapshots to authenticated;

create or replace view public.eco_realtime_notifications_v with(security_invoker=true) as select id,title,body,priority,entity_type,entity_id,deep_link,due_at,status,created_at from public.eco_notifications where employee_id=public.eco_current_employee_id();
create or replace view public.eco_realtime_rider_events_v with(security_invoker=true) as select de.id,de.route_stop_id,de.event_type,de.server_received_at from public.eco_delivery_events de join public.eco_route_stops st on st.id=de.route_stop_id join public.eco_routes r on r.id=st.route_id join public.eco_riders rd on rd.id=r.rider_id where rd.employee_id=public.eco_current_employee_id();
grant select on public.eco_realtime_notifications_v,public.eco_realtime_rider_events_v to authenticated;

