insert into public.eco_metric_definitions(metric_code,version,name_ar,business_question,formula,numerator_definition,denominator_definition,owner_role,data_sources,effective_from) values
('CAC_FULLY_LOADED','v1.0','CAC المحمل بالكامل','كم كلفنا العميل الدافع لأول مرة؟','(Media + Agency + Creative + Influencer + Acquisition Commission + Promo Subsidy) / Unique First-Time Paying Customers','تكاليف الاستحواذ الكاملة','عملاء دفعوا لأول مرة','growth_analyst',array['eco_marketing_spend_daily','eco_customers'],current_date),
('REALIZED_LTV','v1.0','LTV المحقق','كم هامش مساهمة تحقق من العميل؟','Cumulative Posted Contribution Margin per Customer','هامش المساهمة المنشور','العميل','finance_controller',array['eco_journal_lines','eco_customers'],current_date),
('MODELED_LTV','v1.0','LTV المتوقع','ما القيمة المتوقعة حسب ARPA والـChurn؟','Monthly ARPA * Contribution Margin % / Monthly Logo Churn','ARPA × هامش المساهمة','Logo Churn','ceo',array['eco_kpi_snapshots'],current_date),
('LTV_CAC','v1.0','LTV:CAC','هل اقتصاد الاستحواذ صحي؟','Contribution-Margin LTV / Fully-Loaded CAC','LTV','CAC','ceo',array['eco_kpi_snapshots'],current_date),
('LOGO_CHURN','v1.0','Logo Churn','كم عميل بداية الفترة فقدنا؟','Opening Active Customers Churned / Opening Active Customers','عملاء البداية الذين churned','عملاء بداية الفترة','retention_lead',array['eco_subscriptions','eco_subscription_events'],current_date),
('LOGO_RETENTION','v1.0','Logo Retention','كم عميل احتفظنا به؟','(Opening Active - Churned Opening) / Opening Active','العملاء المحتفظ بهم','عملاء بداية الفترة','retention_lead',array['eco_subscriptions'],current_date),
('RENEWAL_RATE','v1.0','نسبة التجديد','كم دورة مستحقة تجددت خلال المهلة؟','Due Cycles Renewed Within Grace / Eligible Due Cycles','دورات تجددت','دورات مستحقة','retention_lead',array['eco_renewal_opportunities'],current_date),
('MRR','v1.0','MRR','ما القيمة الشهرية المتكررة النشطة؟','Normalized Net Recurring Value of Active Paid Contracts','القيمة الشهرية للعقود','N/A','finance_controller',array['eco_subscriptions','eco_invoices'],current_date),
('ARR','v1.0','ARR','ما الإيراد المتكرر السنوي؟','Closing MRR * 12','MRR × 12','N/A','finance_controller',array['eco_kpi_snapshots'],current_date),
('CONTRIBUTION_MARGIN','v1.0','هامش المساهمة','ما المتبقي بعد التكاليف المتغيرة؟','(Net Revenue - Food - Packaging - Variable Delivery - Payment Fees - Variable Service - Refunds) / Net Revenue','هامش المساهمة','صافي الإيراد','finance_controller',array['eco_journal_lines','eco_stock_movements'],current_date),
('DELIVERY_SLA','v1.0','التوصيل في الموعد','كم توصيل ناجح داخل النافذة؟','Successful Deliveries Within Window / Eligible Successful Deliveries','توصيلات داخل الموعد','توصيلات ناجحة','logistics_manager',array['eco_route_stops'],current_date)
on conflict(metric_code,version) do update set formula=excluded.formula,data_sources=excluded.data_sources;

create or replace function public.eco_install_demo_data(p_actor_id uuid) returns jsonb
language plpgsql security definer set search_path=public,pg_temp as $$
declare v_org uuid;v_branch uuid;v_zone uuid;v_window uuid;v_bank uuid;v_ops uuid;v_sales uuid;v_customer uuid;v_address uuid;v_package uuid;v_pv uuid;v_book uuid;v_meal uuid;v_mv uuid;v_month uuid;v_invoice jsonb;v_day date;v_slot text;begin
 perform public.eco_require_actor(p_actor_id,'system.demo.manage');if exists(select 1 from public.eco_customers where is_demo) then return jsonb_build_object('installed',false,'reason','DEMO_ALREADY_EXISTS');end if;
 select organization_id into v_org from public.eco_employees where id=p_actor_id;select id into v_branch from public.eco_branches where organization_id=v_org order by created_at limit 1;
 insert into public.eco_zones(branch_id,code,name_ar,default_delivery_fee) values(v_branch,'Z1','Zone 1',30) on conflict(branch_id,code) do update set name_ar=excluded.name_ar returning id into v_zone;
 insert into public.eco_delivery_windows(branch_id,code,name_ar,start_time,end_time) values(v_branch,'PM1','1:00 - 3:00 م','13:00','15:00') on conflict(branch_id,code) do update set name_ar=excluded.name_ar returning id into v_window;
 insert into public.eco_bank_accounts(branch_id,code,name,account_type,masked_account) values(v_branch,'INSTAPAY','ECO InstaPay','WALLET','***1234') on conflict(branch_id,code) do update set name=excluded.name returning id into v_bank;
 insert into public.eco_employees(organization_id,employee_number,full_name,email,status,is_demo) values(v_org,'DEMO-OPS','Dalia — Demo Operations Manager','dalia.demo@ecohealthy.invalid','ACTIVE',true) returning id into v_ops;
 insert into public.eco_employee_role_assignments(employee_id,role_code,effective_from,approved,approved_by,approved_at,created_by) values(v_ops,'operations_manager',current_date,true,p_actor_id,now(),p_actor_id);
 insert into public.eco_employees(organization_id,employee_number,full_name,email,status,is_demo) values(v_org,'DEMO-SALES','Demo Sales Agent','sales.demo@ecohealthy.invalid','ACTIVE',true) returning id into v_sales;
 insert into public.eco_employee_role_assignments(employee_id,role_code,effective_from,approved,approved_by,approved_at,created_by) values(v_sales,'sales_agent',current_date,true,p_actor_id,now(),p_actor_id);
 insert into public.eco_meals(branch_id,code,name_ar,slot_code) values(v_branch,'L01','Grilled Chicken & Rice','LUNCH') returning id into v_meal;insert into public.eco_meal_versions(meal_id,version_number,effective_from,status,standard_cost,portion_spec) values(v_meal,1,current_date,'APPROVED',92,'{"regular":{"protein_g":100,"carbs_g":150},"hero":{"protein_g":200,"carbs_g":200}}') returning id into v_mv;
 insert into public.eco_packages(branch_id,code,name_ar,sale_category) values(v_branch,'PKG-A','Package A — Lunch','SUBSCRIPTION') returning id into v_package;insert into public.eco_package_versions(package_id,version_number,size_code,service_days,frequency_policy,effective_from,status) values(v_package,1,'REGULAR',24,'DAILY',current_date,'APPROVED') returning id into v_pv;insert into public.eco_package_slots(package_version_id,slot_code,quantity) values(v_pv,'LUNCH',1);
 insert into public.eco_price_books(branch_id,code,name,effective_from,status,approved_by,approved_at) values(v_branch,'DEMO-PRICE','Demo Price Book',current_date,'APPROVED',p_actor_id,now()) returning id into v_book;insert into public.eco_price_book_items(price_book_id,package_version_id,unit_price) values(v_book,v_pv,4628);
 insert into public.eco_menu_months(branch_id,month_start,status) values(v_branch,date_trunc('month',current_date)::date,'APPROVED') returning id into v_month;v_day:=date_trunc('month',current_date)::date;while v_day<(date_trunc('month',current_date)+interval '1 month')::date loop if extract(dow from v_day)<>5 then insert into public.eco_menu_days(menu_month_id,service_date,slot_code,meal_version_id,quantity,updated_by) values(v_month,v_day,'LUNCH',v_mv,1,p_actor_id) on conflict do nothing;end if;v_day:=v_day+1;end loop;
 insert into public.eco_customers(organization_id,customer_number,full_name,normalized_phone,phone_display,email,created_by,is_demo) values(v_org,'DEMO-CUS-001','أحمد علي — تجربة','01090000001','01090000001','demo.customer@ecohealthy.invalid',p_actor_id,true) returning id into v_customer;insert into public.eco_customer_addresses(customer_id,address_line,zone_id,delivery_window_id,is_demo) values(v_customer,'حدائق القبة — عنوان تجريبي',v_zone,v_window,true) returning id into v_address;insert into public.eco_customer_assignments(customer_id,employee_id,assignment_type,effective_from,assigned_by) values(v_customer,v_sales,'SALES_OWNER',current_date,p_actor_id);
 v_invoice:=public.eco_create_priced_invoice(p_actor_id,jsonb_build_object('customer_id',v_customer,'order_type','SUBSCRIPTION','package_version_id',v_pv,'start_date',current_date+1,'address_id',v_address,'delivery_window_id',v_window,'payment_method','INSTAPAY','payment_reference','DEMO-PENDING-001','notes','طلب Demo منتظر رفع إثبات واعتماد الحسابات','idempotency_key','demo-invoice-pending-001'));
 update public.eco_orders set sales_owner_id=v_sales,is_demo=true where id=(v_invoice->>'order_id')::uuid;update public.eco_invoices set is_demo=true where id=(v_invoice->>'invoice_id')::uuid;update public.eco_payments set is_demo=true where id=(v_invoice->>'payment_id')::uuid;
 insert into public.eco_notifications(employee_id,title,body,priority,entity_type,entity_id,deep_link,due_at) values(p_actor_id,'ابدأ سيناريو التجربة','ارفع إثبات الدفع للفاتورة التجريبية ثم اعتمدها من الحسابات','HIGH','invoice',(v_invoice->>'invoice_id')::uuid,'/accounting',now()+interval '1 day');
 return jsonb_build_object('installed',true,'demo_customer_id',v_customer,'pending_invoice_id',v_invoice->>'invoice_id','dalia_role','operations_manager','next_step','UPLOAD_PAYMENT_PROOF_THEN_VERIFY');
end $$;

grant execute on function public.eco_install_demo_data(uuid) to service_role;

-- Migration audit helpers: legacy imports must populate these issues instead of trusting derived totals.
create or replace view public.eco_migration_duplicate_customers_v as select normalized_phone,count(*) duplicate_count,array_agg(id) customer_ids from public.eco_customers group by normalized_phone having count(*)>1;
create or replace view public.eco_migration_payment_differences_v as select i.id invoice_id,i.invoice_number,i.total,coalesce(sum(pa.amount),0) allocated_amount,i.total-coalesce(sum(pa.amount),0) difference from public.eco_invoices i left join public.eco_payment_allocations pa on pa.invoice_id=i.id group by i.id having i.total<>coalesce(sum(pa.amount),0) and i.status='PAID';
create or replace view public.eco_migration_missing_proof_v as select p.id payment_id,p.reference,'MISSING_LEGACY_EVIDENCE' issue from public.eco_payments p where p.method<>'CASH' and p.status='VERIFIED' and not exists(select 1 from public.eco_payment_proofs pp where pp.payment_id=p.id);
revoke all on public.eco_migration_duplicate_customers_v,public.eco_migration_payment_differences_v,public.eco_migration_missing_proof_v from public,anon,authenticated;
grant select on public.eco_migration_duplicate_customers_v,public.eco_migration_payment_differences_v,public.eco_migration_missing_proof_v to service_role;

select pg_notify('pgrst','reload schema');

create table if not exists public.eco_api_rate_limits(bucket_key text primary key,window_started_at timestamptz not null,request_count integer not null check(request_count>0),updated_at timestamptz not null default now());
alter table public.eco_api_rate_limits enable row level security;revoke all on public.eco_api_rate_limits from public,anon,authenticated;
create or replace function public.eco_take_rate_limit(p_bucket_key text,p_limit integer,p_window_seconds integer) returns boolean language plpgsql security definer set search_path=public,pg_temp as $$ declare v_count integer;begin if length(p_bucket_key)<>64 or p_limit<1 or p_window_seconds<1 then raise exception 'ECO_INVALID_RATE_LIMIT';end if;insert into public.eco_api_rate_limits(bucket_key,window_started_at,request_count) values(p_bucket_key,now(),1) on conflict(bucket_key) do update set window_started_at=case when public.eco_api_rate_limits.window_started_at+make_interval(secs=>p_window_seconds)<=now() then now() else public.eco_api_rate_limits.window_started_at end,request_count=case when public.eco_api_rate_limits.window_started_at+make_interval(secs=>p_window_seconds)<=now() then 1 else public.eco_api_rate_limits.request_count+1 end,updated_at=now() returning request_count into v_count;return v_count<=p_limit;end $$;
revoke all on function public.eco_take_rate_limit(text,integer,integer) from public,anon,authenticated;grant execute on function public.eco_take_rate_limit(text,integer,integer) to service_role;
